    ; __append("\r\n</section>\r\n\r\n<!-- 確認モーダル -->\r\n<div id=\"badge-modal-overlay\">\r\n  <div id=\"badge-modal\">\r\n    <h4 id=\"modal-title\"></h4>\r\n    <p id=\"modal-body\"></p>\r\n    <div class=\"modal-actions\">\r\n      <button class=\"btn-cancel\" onclick=\"closeModal()\">キャンセル</button>\r\n      <button class=\"btn-confirm\" id=\"modal-confirm\" onclick=\"confirmToggle()\"></button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<script>\r\nlet _pendingCheckbox = null;\r\nlet _pendingIsActive = false;\r\n\r\nfunction requestToggle(checkbox) {\r\n  const id = checkbox.dataset.id;\r\n  const name = checkbox.dataset.name;\r\n  const isActive = checkbox.checked;\r\n\r\n  // 即座に revert（確認後に apply）\r\n  checkbox.checked = !isActive;\r\n  checkbox.disabled = true;\r\n\r\n  _pendingCheckbox = checkbox;\r\n  _pendingIsActive = isActive;\r\n\r\n  const title = document.getElementById('modal-title');\r\n  const body  = document.getElementById('modal-body');\r\n  const btn   = document.getElementById('modal-confirm');\r\n\r\n  if (isActive) {\r\n    title.textContent = '有効にする';\r\n    body.textContent  = 'このバッジを有効にしますか？「' + name + '」';\r\n    btn.textContent   = '有効化';\r\n    btn.className     = 'btn-confirm activate';\r\n  } else {\r\n    title.textContent = '無効にする';\r\n    body.textContent  = 'このバッジを無効にしますか？「' + name + '」\\n\\n無効化しても既に獲得済みのバッジは剥奪されません。';\r\n    btn.textContent   = '無効化';\r\n    btn.className     = 'btn-confirm deactivate';\r\n  }\r\n\r\n  document.getElementById('badge-modal-overlay').classList.add('open');\r\n}\r\n\r\nfunction closeModal() {\r\n  document.getElementById('badge-modal-overlay').classList.remove('open');\r\n  if (_pendingCheckbox) {\r\n    _pendingCheckbox.disabled = false;\r\n    _pendingCheckbox = null;\r\n  }\r\n}\r\n\r\nasync function confirmToggle() {\r\n  const checkbox  = _pendingCheckbox;\r\n  const isActive  = _pendingIsActive;\r\n  const id        = checkbox.dataset.id;\r\n\r\n  document.getElementById('badge-modal-overlay').classList.remove('open');\r\n  checkbox.disabled = true;\r\n\r\n  try {\r\n    const res = await fetch('/admin/badges/' + id + '/status', {\r\n      method: 'PATCH',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ isActive })\r\n    });\r\n    if (!res.ok) {\r\n      let errMsg = 'HTTP ' + res.status;\r\n      try {\r\n        const body = await res.json();\r\n        if (body && body.error) errMsg = body.error;\r\n      } catch (_) { /* ignore parse error */ }\r\n      console.error('[badge] updateStatus failed', { id, isActive, status: res.status, errMsg });\r\n      throw new Error(errMsg);\r\n    }\r\n\r\n    // DOM を更新\r\n    checkbox.checked = isActive;\r\n    const row = checkbox.closest('tr');\r\n    const label = row.querySelector('.status-label');\r\n\r\n    if (isActive) {\r\n      row.style.opacity = '';\r\n      row.dataset.active = 'true';\r\n      label.style.color = '#2ca87a';\r\n      label.textContent = '● 有効';\r\n    } else {\r\n      row.style.opacity = '.5';\r\n      row.dataset.active = 'false';\r\n      label.style.color = '#999';\r\n      label.textContent = '● 無効';\r\n    }\r\n\r\n    applyFilter();\r\n  } catch (e) {\r\n    const reason = e instanceof Error ? e.message : String(e);\r\n    alert('更新に失敗しました。\\n原因: ' + reason + '\\n\\nページをリロードしてください。');\r\n    console.error('[badge] confirmToggle error', e);\r\n  } finally {\r\n    checkbox.disabled = false;\r\n    _pendingCheckbox = null;\r\n  }\r\n}\r\n\r\nfunction applyFilter() {\r\n  const val  = document.getElementById('statusFilter').value;\r\n  const rows = document.querySelectorAll('#badge-tbody tr[data-badge-id]');\r\n  let visible = 0;\r\n\r\n  rows.forEach(row => {\r\n    const active = row.dataset.active === 'true';\r\n    let show = true;\r\n    if (val === 'active')   show = active;\r\n    if (val === 'inactive') show = !active;\r\n    row.style.display = show ? '' : 'none';\r\n    if (show) visible++;\r\n  });\r\n\r\n  document.getElementById('visible-count').textContent = visible;\r\n}\r\n\r\n// オーバーレイクリックで閉じる\r\ndocument.getElementById('badge-modal-overlay').addEventListener('click', function(e) {\r\n  if (e.target === this) closeModal();\r\n});\r\n</script>\r\n\r\n")
