    ; __append("\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n\r\n<!-- ========== 確認モーダル ========== -->\r\n<div class=\"modal-overlay\" id=\"confirm-modal\" onclick=\"handleModalOverlayClick(event)\">\r\n  <div class=\"modal-box\">\r\n    <div class=\"modal-title\">配信確認</div>\r\n    <div class=\"modal-sub\">以下の内容で配信を実行します。よろしいですか？</div>\r\n    <table class=\"confirm-table\">\r\n      <tbody>\r\n        <tr><td>対象案件</td><td id=\"modal-project\"></td></tr>\r\n        <tr>\r\n          <td>実際の対象人数</td>\r\n          <td id=\"modal-count\" style=\"font-size:18px;color:#117a37\"></td>\r\n        </tr>\r\n        <tr><td>セグメント</td><td id=\"modal-segment\"></td></tr>\r\n        <tr><td>キャンペーン</td><td id=\"modal-campaign\"></td></tr>\r\n        <tr><td>同意書類</td><td id=\"modal-documents\"></td></tr>\r\n      </tbody>\r\n    </table>\r\n\r\n    <!-- セグメント未選択＝全会員配信。最も影響が大きいケースなので明示的な同意を要求する -->\r\n    <div id=\"modal-allmembers-warning\" class=\"confirm-panel\" style=\"display:none;margin-top:12px\">\r\n      <div><strong>全会員への配信です。</strong></div>\r\n      <div class=\"muted\" style=\"font-size:13px;margin-top:4px\">\r\n        セグメントが選択されていないため、条件を満たす全ユーザーが対象になります。\r\n      </div>\r\n    </div>\r\n\r\n    <label class=\"confirm-ack\">\r\n      <input type=\"checkbox\" id=\"modal-ack\" onchange=\"document.getElementById('modal-confirm-btn').disabled = !this.checked\" />\r\n      <span id=\"modal-ack-text\">上記の内容を確認しました</span>\r\n    </label>\r\n\r\n    <div class=\"modal-actions\">\r\n      <button class=\"btn-cancel\" onclick=\"closeModal()\">キャンセル</button>\r\n      <button class=\"btn-execute\" id=\"modal-confirm-btn\" onclick=\"executeDelivery()\" disabled>\r\n        配信を実行\r\n      </button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<script>\r\n  // ============================================================\r\n  // 静的データ\r\n  // ============================================================\r\n  const PROJECTS_DATA = ")
    ; __append( JSON.stringify(projects) )
    ; __append(";\r\n  const CAMPAIGNS_DATA = ")
    ; __append( JSON.stringify(campaigns) )
    ; __append(";\r\n  const SEGMENTS_DATA = ")
    ; __append( JSON.stringify(segments) )
    ; __append(";\r\n  const NOTIFICATION_TEMPLATES_DATA = ")
    ; __append( JSON.stringify(notificationTemplates) )
    ; __append(";\r\n  const GLOBAL_CONSENT_DOCUMENTS_DATA = ")
    ; __append( JSON.stringify(globalConsentDocuments || []) )
    ; __append(";\r\n\r\n  const DS_LABELS = {\r\n    undelivered: '未配信',\r\n    ready: '配信準備中',\r\n    scheduled: '配信予約済',\r\n    in_progress: '配信中',\r\n    completed: '配信終了',\r\n    paused: '停止中',\r\n  };\r\n  const CAMPAIGN_STATUS_LABELS = { draft: '下書き', scheduled: '予約済', sent: '送信済', cancelled: 'キャンセル' };\r\n  const CAMPAIGN_STATUS_COLORS = { draft: '#6a7b78', scheduled: '#0a56a8', sent: '#117a37', cancelled: '#b42318' };\r\n\r\n  // ============================================================\r\n  // 状態\r\n  // ============================================================\r\n  let currentFilter = 'all';\r\n  let selectedProjectId = null;\r\n  let selectedCampaignId = null;\r\n  let selectedSegmentId = null;\r\n  let selectedTemplateId = null;\r\n  let draggedProjectId = null;\r\n\r\n  // ============================================================\r\n  // フィルタ / ソート\r\n  // ============================================================\r\n  function setFilter(status, btn) {\r\n    currentFilter = status;\r\n    document.querySelectorAll('.filter-pill').forEach(el => el.classList.remove('active'));\r\n    btn.classList.add('active');\r\n    applyFilterSort();\r\n  }\r\n\r\n  function applySort(sortKey) {\r\n    applyFilterSort(sortKey);\r\n  }\r\n\r\n  function applyFilterSort(sortKey) {\r\n    sortKey = sortKey || document.getElementById('sort-select').value;\r\n    const cards = Array.from(document.querySelectorAll('#project-list .proj-card'));\r\n\r\n    cards.forEach(card => {\r\n      const st = card.dataset.status;\r\n      card.style.display = (currentFilter === 'all' || st === currentFilter) ? '' : 'none';\r\n    });\r\n\r\n    const visible = cards.filter(c => c.style.display !== 'none');\r\n    visible.sort((a, b) => {\r\n      if (sortKey === 'points') return parseInt(b.dataset.points) - parseInt(a.dataset.points);\r\n      if (sortKey === 'campaigns') return parseInt(b.dataset.campaigns) - parseInt(a.dataset.campaigns);\r\n      return 0;\r\n    });\r\n    const list = document.getElementById('project-list');\r\n    visible.forEach(c => list.appendChild(c));\r\n  }\r\n\r\n  // ============================================================\r\n  // プロジェクト選択\r\n  // ============================================================\r\n  function selectProject(projectId) {\r\n    selectedProjectId = projectId;\r\n    selectedCampaignId = null;\r\n    selectedSegmentId = null;\r\n    selectedTemplateId = null;\r\n\r\n    document.querySelectorAll('.proj-card').forEach(c =>\r\n      c.classList.toggle('selected', c.dataset.id === projectId));\r\n\r\n    const project = PROJECTS_DATA.find(p => p.id === projectId);\r\n    if (!project) return;\r\n\r\n    document.getElementById('no-selection').style.display = 'none';\r\n    document.getElementById('project-work-area').style.display = '';\r\n\r\n    document.getElementById('sel-project-name').textContent = project.name;\r\n    document.getElementById('sel-project-status').textContent = project.status;\r\n    document.getElementById('sel-project-points').textContent = project.reward_points;\r\n    document.getElementById('sel-delivery-status-badge').innerHTML =\r\n      `<span class=\"ds-badge ds-${project.deliveryStatus}\">${DS_LABELS[project.deliveryStatus] || project.deliveryStatus}</span>`;\r\n    document.getElementById('sel-project-link').href = `/admin/projects/${projectId}/delivery`;\r\n    document.getElementById('new-campaign-link').href =\r\n      `/admin/segments/campaigns/new?project_id=${projectId}`;\r\n\r\n    // キャンペーンドロップダウン（プロジェクト固有 + 全体配信 project_id=null）\r\n    const projectCampaigns = CAMPAIGNS_DATA.filter(\r\n      c => c.project_id === projectId || c.project_id === null\r\n    );\r\n    renderCampaignDropdown(projectCampaigns);\r\n\r\n    // セグメントドロップダウン\r\n    renderSegmentDropdown();\r\n\r\n    // テンプレートドロップダウン\r\n    renderTemplateDropdown();\r\n\r\n    // 同意書類\r\n    renderDocumentRequirements(project);\r\n\r\n    // 詳細・情報欄リセット\r\n    document.getElementById('campaign-detail').style.display = 'none';\r\n    document.getElementById('sel-segment-info').textContent = '';\r\n    document.getElementById('sel-template-info').textContent = '';\r\n    updateExecuteBtn();\r\n\r\n    hidePreview();\r\n\r\n    document.querySelectorAll('#summary-table tbody tr').forEach(row => {\r\n      const btn = row.querySelector('button');\r\n      if (btn && btn.getAttribute('onclick') === `selectProject('${projectId}')`) {\r\n        row.style.background = '#f0fbf9';\r\n      } else {\r\n        row.style.background = '';\r\n      }\r\n    });\r\n  }\r\n\r\n  // ============================================================\r\n  // 同意書類\r\n  // ============================================================\r\n  function getConsentDocuments(project) {\r\n    const byId = new Map();\r\n    for (const doc of GLOBAL_CONSENT_DOCUMENTS_DATA) {\r\n      byId.set(doc.documentId, { ...doc, scope: '全体必須', isRequired: true });\r\n    }\r\n    for (const doc of (project.documentRequirements || [])) {\r\n      const existing = byId.get(doc.documentId);\r\n      if (existing) {\r\n        existing.scope = existing.scope + ' / 案件';\r\n        existing.isRequired = existing.isRequired || doc.isRequired;\r\n      } else {\r\n        byId.set(doc.documentId, {\r\n          ...doc,\r\n          scope: doc.isRequired ? '案件必須' : '案件任意',\r\n        });\r\n      }\r\n    }\r\n    return Array.from(byId.values());\r\n  }\r\n\r\n  function formatConsentDocumentSummary(project) {\r\n    const docs = getConsentDocuments(project);\r\n    if (docs.length === 0) return 'なし';\r\n    const requiredCount = docs.filter(d => d.isRequired).length;\r\n    return `${docs.length}件（必須 ${requiredCount}件）`;\r\n  }\r\n\r\n  function renderDocumentRequirements(project) {\r\n    const el = document.getElementById('sel-documents-info');\r\n    if (!el) return;\r\n\r\n    const docs = getConsentDocuments(project);\r\n    if (docs.length === 0) {\r\n      el.innerHTML = `\r\n        <div style=\"color:#6a7b78\">この案件に紐づく同意書類はありません。</div>\r\n        <a href=\"/admin/documents\" style=\"display:inline-block;margin-top:6px;color:#0b7a75\">書類管理を開く</a>`;\r\n      return;\r\n    }\r\n\r\n    el.innerHTML = `\r\n      <div style=\"display:flex;justify-content:space-between;align-items:center;gap:8px\">\r\n        <strong>${formatConsentDocumentSummary(project)}</strong>\r\n        <a href=\"/admin/documents\" style=\"color:#0b7a75;white-space:nowrap\">書類管理</a>\r\n      </div>\r\n      <div class=\"doc-requirements-list\">\r\n        ${docs.map(doc => `\r\n          <div class=\"doc-requirement-row\" title=\"${escHtml(doc.title)}\">\r\n            <span class=\"doc-requirement-name\">${escHtml(doc.title)}</span>\r\n            <span class=\"doc-requirement-meta\">${escHtml(doc.scope)} / v${escHtml(doc.versionNo || '-')}</span>\r\n          </div>`).join('')}\r\n      </div>`;\r\n  }\r\n\r\n  // ============================================================\r\n  // ドロップダウン描画\r\n  // ============================================================\r\n  function renderCampaignDropdown(campaigns) {\r\n    const sel = document.getElementById('campaign-select');\r\n    sel.innerHTML = '<option value=\"\">-- キャンペーンを選択 --</option>';\r\n    campaigns.forEach(c => {\r\n      const opt = document.createElement('option');\r\n      opt.value = c.id;\r\n      const globalTag = c.project_id === null ? ' [全体]' : '';\r\n      opt.textContent = `${c.name}${globalTag}  [${CAMPAIGN_STATUS_LABELS[c.status] || c.status}]`;\r\n      sel.appendChild(opt);\r\n    });\r\n    if (campaigns.length === 0) {\r\n      const opt = document.createElement('option');\r\n      opt.disabled = true;\r\n      opt.textContent = '（このプロジェクトのキャンペーンはありません）';\r\n      sel.appendChild(opt);\r\n    }\r\n  }\r\n\r\n  function renderSegmentDropdown() {\r\n    const sel = document.getElementById('segment-select');\r\n    sel.innerHTML = '<option value=\"\">-- セグメントを選択（全会員） --</option>';\r\n    const guide = document.getElementById('segment-guide');\r\n    if (SEGMENTS_DATA.length === 0) {\r\n      guide.style.display = '';\r\n    } else {\r\n      guide.style.display = 'none';\r\n      SEGMENTS_DATA.forEach(s => {\r\n        const opt = document.createElement('option');\r\n        opt.value = s.id;\r\n        const countText = s.estimated_count != null ? ` (${s.estimated_count}名)` : '';\r\n        opt.textContent = s.name + countText;\r\n        sel.appendChild(opt);\r\n      });\r\n    }\r\n  }\r\n\r\n  function renderTemplateDropdown() {\r\n    const sel = document.getElementById('template-select');\r\n    sel.innerHTML = '<option value=\"\">-- テンプレートを選択 --</option>';\r\n    NOTIFICATION_TEMPLATES_DATA.forEach(t => {\r\n      const opt = document.createElement('option');\r\n      opt.value = t.id;\r\n      opt.textContent = t.name;\r\n      sel.appendChild(opt);\r\n    });\r\n  }\r\n\r\n  // ============================================================\r\n  // キャンペーン選択\r\n  // ============================================================\r\n  function selectCampaign(campaignId) {\r\n    selectedCampaignId = campaignId || null;\r\n\r\n    const detail = document.getElementById('campaign-detail');\r\n    if (!campaignId) {\r\n      detail.style.display = 'none';\r\n      updateExecuteBtn();\r\n      maybeUpdatePreview();\r\n      return;\r\n    }\r\n\r\n    const campaign = CAMPAIGNS_DATA.find(c => c.id === campaignId);\r\n    if (!campaign) return;\r\n\r\n    detail.innerHTML = `\r\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:4px\">\r\n        <strong>${escHtml(campaign.name)}</strong>\r\n        <span style=\"color:${CAMPAIGN_STATUS_COLORS[campaign.status] || '#333'};font-weight:700\">\r\n          ${CAMPAIGN_STATUS_LABELS[campaign.status] || campaign.status}\r\n        </span>\r\n      </div>\r\n      <div style=\"color:#6a7b78\">\r\n        送信 ${campaign.sent_count}名 | 完了 ${campaign.completed_count}名\r\n        ${campaign.scheduled_at ? ` | 予定: ${new Date(campaign.scheduled_at).toLocaleString('ja-JP')}` : ''}\r\n      </div>`;\r\n    detail.style.display = '';\r\n\r\n    // キャンペーンにセグメントが紐付いていれば自動選択\r\n    if (campaign.segment_id) {\r\n      const sel = document.getElementById('segment-select');\r\n      sel.value = campaign.segment_id;\r\n      selectSegment(campaign.segment_id);\r\n    }\r\n\r\n    updateExecuteBtn();\r\n    maybeUpdatePreview();\r\n  }\r\n\r\n  // ============================================================\r\n  // セグメント選択\r\n  // ============================================================\r\n  function selectSegment(segmentId) {\r\n    selectedSegmentId = segmentId || null;\r\n\r\n    const infoEl = document.getElementById('sel-segment-info');\r\n    if (!segmentId) {\r\n      infoEl.textContent = '全会員が対象です';\r\n      maybeUpdatePreview();\r\n      return;\r\n    }\r\n\r\n    const seg = SEGMENTS_DATA.find(s => s.id === segmentId);\r\n    if (seg) {\r\n      const count = seg.estimated_count != null ? `推定 ${seg.estimated_count}名` : '人数未評価';\r\n      infoEl.innerHTML = `対象: <strong>${escHtml(seg.name)}</strong>（${count}）`;\r\n    }\r\n    maybeUpdatePreview();\r\n  }\r\n\r\n  // ============================================================\r\n  // 通知テンプレート選択\r\n  // ============================================================\r\n  function selectTemplate(templateId) {\r\n    selectedTemplateId = templateId || null;\r\n\r\n    const infoEl = document.getElementById('sel-template-info');\r\n    if (!templateId) {\r\n      infoEl.textContent = '';\r\n      maybeUpdatePreview();\r\n      return;\r\n    }\r\n\r\n    const tmpl = NOTIFICATION_TEMPLATES_DATA.find(t => t.id === templateId);\r\n    if (tmpl) {\r\n      infoEl.textContent = tmpl.description || tmpl.name;\r\n    }\r\n    maybeUpdatePreview();\r\n  }\r\n\r\n  // ============================================================\r\n  // プレビュー\r\n  // ============================================================\r\n  function maybeUpdatePreview() {\r\n    if (selectedProjectId) updatePreview();\r\n  }\r\n\r\n  function updatePreview() {\r\n    const project = PROJECTS_DATA.find(p => p.id === selectedProjectId);\r\n    if (!project) return;\r\n\r\n    const seg = selectedSegmentId ? SEGMENTS_DATA.find(s => s.id === selectedSegmentId) : null;\r\n    const tmpl = selectedTemplateId ? NOTIFICATION_TEMPLATES_DATA.find(t => t.id === selectedTemplateId) : null;\r\n    const campaign = selectedCampaignId ? CAMPAIGNS_DATA.find(c => c.id === selectedCampaignId) : null;\r\n\r\n    const countText = seg && seg.estimated_count != null ? `${seg.estimated_count}名` : '全会員';\r\n\r\n    // LINE吹き出し\r\n    const title = tmpl ? (tmpl.title_text || project.name) : `🎯 ${project.name}`;\r\n    const body = tmpl ? tmpl.body_text : `${project.reward_points}ptを獲得できます！\\n\\nご協力をお願いします。`;\r\n    const actionLabel = tmpl ? (tmpl.action_label || '回答する') : '回答する';\r\n\r\n    document.getElementById('preview-title').textContent = title;\r\n    document.getElementById('preview-body').textContent = body;\r\n    document.querySelector('.line-bubble-action').textContent = actionLabel;\r\n\r\n    // サマリ\r\n    document.getElementById('sum-project').textContent = project.name;\r\n    document.getElementById('sum-segment').textContent = seg ? seg.name : '全会員';\r\n    document.getElementById('sum-count').textContent = countText;\r\n    document.getElementById('sum-template').textContent = tmpl ? tmpl.name : '（未選択）';\r\n    document.getElementById('sum-campaign').textContent = campaign ? campaign.name : '（未選択）';\r\n    document.getElementById('sum-documents').textContent = formatConsentDocumentSummary(project);\r\n\r\n    document.getElementById('preview-empty').style.display = 'none';\r\n    document.getElementById('preview-content').style.display = 'flex';\r\n    document.getElementById('preview-content').style.flexDirection = 'column';\r\n  }\r\n\r\n  function hidePreview() {\r\n    document.getElementById('preview-empty').style.display = '';\r\n    document.getElementById('preview-content').style.display = 'none';\r\n  }\r\n\r\n  function updateExecuteBtn() {\r\n    const btn = document.getElementById('execute-btn');\r\n    btn.disabled = !(selectedProjectId && selectedCampaignId);\r\n  }\r\n\r\n  // ============================================================\r\n  // 確認モーダル\r\n  // ============================================================\r\n  async function showConfirmModal() {\r\n    if (!selectedProjectId || !selectedCampaignId) return;\r\n\r\n    const project = PROJECTS_DATA.find(p => p.id === selectedProjectId);\r\n    const campaign = CAMPAIGNS_DATA.find(c => c.id === selectedCampaignId);\r\n    if (!project || !campaign) return;\r\n\r\n    const seg = selectedSegmentId ? SEGMENTS_DATA.find(s => s.id === selectedSegmentId) : null;\r\n\r\n    document.getElementById('modal-project').textContent = project.name;\r\n    document.getElementById('modal-segment').textContent = seg ? seg.name : '全会員（セグメント未選択）';\r\n    document.getElementById('modal-campaign').textContent = campaign.name;\r\n    document.getElementById('modal-documents').textContent = formatConsentDocumentSummary(project);\r\n    document.getElementById('modal-allmembers-warning').style.display = seg ? 'none' : '';\r\n\r\n    // 確認は「実行してよいと分かった状態」からしか押せないようにする\r\n    const ack = document.getElementById('modal-ack');\r\n    ack.checked = false;\r\n    const confirmBtn = document.getElementById('modal-confirm-btn');\r\n    confirmBtn.disabled = true;\r\n    confirmBtn.textContent = '配信を実行';\r\n\r\n    // 件数はセグメントに保存された estimated_count（古い可能性がある）ではなく、\r\n    // 実配信と同じ経路のドライランで取り直す。\r\n    const countCell = document.getElementById('modal-count');\r\n    countCell.textContent = '対象を確認中...';\r\n    document.getElementById('confirm-modal').classList.add('active');\r\n\r\n    try {\r\n      const res = await fetch(`/admin/api/campaigns/${selectedCampaignId}/execute`, {\r\n        method: 'POST',\r\n        headers: { 'Content-Type': 'application/json' },\r\n        body: JSON.stringify({\r\n          segment_id: selectedSegmentId || null,\r\n          project_id: selectedProjectId || null,\r\n          dry_run: '1',\r\n        }),\r\n      });\r\n      const data = await res.json();\r\n      if (!res.ok) {\r\n        countCell.textContent = '取得できませんでした';\r\n        countCell.style.color = '#b42318';\r\n        document.getElementById('modal-ack-text').textContent =\r\n          '対象人数を確認できませんでした：' + (data.error || '不明なエラー');\r\n        return;\r\n      }\r\n      countCell.style.color = '#117a37';\r\n      countCell.textContent = `${(data.target_count || 0).toLocaleString('ja-JP')}名`;\r\n      document.getElementById('modal-ack-text').textContent =\r\n        `${(data.target_count || 0).toLocaleString('ja-JP')}名に配信することを確認しました`;\r\n      if (!data.target_count) {\r\n        document.getElementById('modal-ack-text').textContent =\r\n          '対象者が0名です。配信しても何も送信されません。';\r\n      }\r\n    } catch {\r\n      countCell.textContent = '取得できませんでした';\r\n      countCell.style.color = '#b42318';\r\n    }\r\n  }\r\n\r\n  function closeModal() {\r\n    document.getElementById('confirm-modal').classList.remove('active');\r\n  }\r\n\r\n  function handleModalOverlayClick(e) {\r\n    if (e.target === document.getElementById('confirm-modal')) closeModal();\r\n  }\r\n\r\n  async function executeDelivery() {\r\n    if (!selectedCampaignId) return;\r\n    const btn = document.getElementById('modal-confirm-btn');\r\n    btn.textContent = '送信中...';\r\n    btn.disabled = true;\r\n\r\n    try {\r\n      const res = await fetch(`/admin/api/campaigns/${selectedCampaignId}/execute`, {\r\n        method: 'POST',\r\n        headers: { 'Content-Type': 'application/json' },\r\n        body: JSON.stringify({\r\n          segment_id: selectedSegmentId || null,\r\n          project_id: selectedProjectId || null,\r\n          notification_template_id: selectedTemplateId || null,\r\n        }),\r\n      });\r\n      const data = await res.json();\r\n      if (res.ok) {\r\n        closeModal();\r\n        // このエンドポイントが行うのは案件のアサインまで。LINE push は別経路なので、\r\n        // 「送信数」と呼ぶと実際に通知が飛んだと誤解される。\r\n        alert(`${data.sent_count || 0}名に案件をアサインしました。\\n（LINE通知の送信は配信テンプレート／スケジューラ側で行われます）`);\r\n        location.reload();\r\n      } else {\r\n        alert(`エラー: ${data.error || '配信に失敗しました'}`);\r\n        btn.disabled = false;\r\n        btn.textContent = '配信を実行';\r\n      }\r\n    } catch {\r\n      alert('通信エラーが発生しました');\r\n      btn.disabled = false;\r\n      btn.textContent = '配信を実行';\r\n    }\r\n  }\r\n\r\n  // ============================================================\r\n  // カンバン ドラッグ & ドロップ\r\n  // ============================================================\r\n  function handleDragStart(event, projectId) {\r\n    draggedProjectId = projectId;\r\n    event.dataTransfer.effectAllowed = 'move';\r\n  }\r\n\r\n  async function handleDrop(event, targetStatus) {\r\n    event.preventDefault();\r\n    event.currentTarget.classList.remove('drag-over');\r\n    if (!draggedProjectId) return;\r\n\r\n    const project = PROJECTS_DATA.find(p => p.id === draggedProjectId);\r\n    if (!project || project.deliveryStatus === targetStatus) {\r\n      draggedProjectId = null;\r\n      return;\r\n    }\r\n\r\n    if (targetStatus === 'ready') {\r\n      if (!confirm(`「${project.name}」を配信準備中に変更します。\\n（delivery_enabled = true に設定）`)) {\r\n        draggedProjectId = null;\r\n        return;\r\n      }\r\n      await patchProjectDelivery(draggedProjectId, true);\r\n    } else if (targetStatus === 'undelivered' || targetStatus === 'paused') {\r\n      if (!confirm(`「${project.name}」の自動配信を無効化します。\\n（delivery_enabled = false に設定）`)) {\r\n        draggedProjectId = null;\r\n        return;\r\n      }\r\n      await patchProjectDelivery(draggedProjectId, false);\r\n    } else {\r\n      alert(`「${DS_LABELS[targetStatus] || targetStatus}」への変更は\\nキャンペーン画面から行ってください。`);\r\n    }\r\n\r\n    draggedProjectId = null;\r\n  }\r\n\r\n  async function patchProjectDelivery(projectId, deliveryEnabled) {\r\n    try {\r\n      const res = await fetch('/admin/api/delivery-operations/update-project', {\r\n        method: 'POST',\r\n        headers: { 'Content-Type': 'application/json' },\r\n        body: JSON.stringify({ project_id: projectId, delivery_enabled: deliveryEnabled }),\r\n      });\r\n      if (res.ok) {\r\n        location.reload();\r\n      } else {\r\n        alert('更新に失敗しました');\r\n      }\r\n    } catch {\r\n      alert('通信エラーが発生しました');\r\n    }\r\n  }\r\n\r\n  // ============================================================\r\n  // テーブル検索\r\n  // ============================================================\r\n  function filterTable(query) {\r\n    const q = query.toLowerCase();\r\n    document.querySelectorAll('#summary-table tbody tr').forEach(row => {\r\n      const name = (row.dataset.name || '');\r\n      row.style.display = name.includes(q) ? '' : 'none';\r\n    });\r\n  }\r\n\r\n  // ============================================================\r\n  // ユーティリティ\r\n  // ============================================================\r\n  function escHtml(str) {\r\n    return String(str)\r\n      .replace(/&/g, '&amp;')\r\n      .replace(/</g, '&lt;')\r\n      .replace(/>/g, '&gt;')\r\n      .replace(/\"/g, '&quot;');\r\n  }\r\n</script>\r\n\r\n")
