    ; __append( JSON.stringify(nextQuestionOptions) )
    ; __append(";\r\n\r\n  function attachRemoveRow(container) {\r\n    container.querySelectorAll('.remove-row').forEach(btn => {\r\n      btn.onclick = () => {\r\n        const rows = container.querySelectorAll('.row-card');\r\n        if (rows.length <= 1) {\r\n          rows[0].querySelectorAll('input, select, textarea').forEach(f => {\r\n            if (f.tagName === 'SELECT') f.selectedIndex = 0;\r\n            else f.value = '';\r\n          });\r\n          return;\r\n        }\r\n        btn.closest('.row-card').remove();\r\n      };\r\n    });\r\n  }\r\n\r\n  function makeOptionRow(value = '', imageUrl = '', extraImages = '', description = '') {\r\n    const d = document.createElement('div');\r\n    d.className = 'row-card option-row';\r\n    d.innerHTML = `\r\n      <div style=\"display:flex;gap:8px;align-items:flex-start;flex-wrap:wrap;\">\r\n        <label style=\"flex:1;min-width:160px;\">選択肢テキスト\r\n          <input type=\"text\" name=\"option_labels\" value=\"${escHtml(value)}\" placeholder=\"例: 毎日\" />\r\n          <input type=\"hidden\" name=\"option_screening_pass\" value=\"0\" class=\"screening-pass-hidden\" />\r\n          <label class=\"screening-pass-label\" style=\"margin-top:4px;display:flex;align-items:center;gap:5px;font-size:12px;font-weight:normal;\">\r\n            <input type=\"checkbox\" class=\"screening-pass-check\"\r\n              onchange=\"this.closest('.option-row').querySelector('.screening-pass-hidden').value = this.checked ? '1' : '0'\" />\r\n            スクリーニング通過対象\r\n          </label>\r\n        </label>\r\n        <div style=\"flex:2;min-width:200px;\">\r\n          <label>メイン画像URL（省略可）</label>\r\n          <div style=\"display:flex;gap:4px;align-items:center;\">\r\n            <input type=\"url\" name=\"option_image_urls\" class=\"option-image-url\"\r\n              value=\"${escHtml(imageUrl)}\" placeholder=\"https://... または空欄\"\r\n              style=\"flex:1;\" oninput=\"syncImagePreview(this)\" />\r\n            <label class=\"button-link secondary\" style=\"white-space:nowrap;cursor:pointer;\">ファイル選択\r\n              <input type=\"file\" accept=\"image/png,image/jpeg,image/webp\" class=\"option-file-input\" hidden />\r\n            </label>\r\n          </div>\r\n          <div class=\"option-image-preview\" style=\"margin-top:4px;${imageUrl ? '' : 'display:none;'}\">\r\n            <img src=\"${escHtml(imageUrl)}\" alt=\"preview\"\r\n              style=\"max-width:120px;max-height:80px;border-radius:4px;border:1px solid #ddd;\"\r\n              onerror=\"this.parentElement.style.display='none'\" />\r\n            <button type=\"button\" class=\"button-link danger remove-image\" style=\"font-size:12px;\">削除</button>\r\n          </div>\r\n          <label style=\"margin-top:6px;font-size:12px;color:#60726f;\">\r\n            追加画像URL（改行区切り・複数枚表示）\r\n            <textarea name=\"option_extra_image_urls\" rows=\"2\"\r\n              placeholder=\"https://...&#10;https://...\"\r\n              style=\"font-size:12px;\">${escHtml(extraImages)}</textarea>\r\n          </label>\r\n        </div>\r\n        <label style=\"flex:2;min-width:160px;\">補足説明（省略可）\r\n          <input type=\"text\" name=\"option_descriptions\" value=\"${escHtml(description)}\" placeholder=\"例: 商品名・説明\" />\r\n        </label>\r\n      </div>\r\n      <div class=\"inline-actions\"><button type=\"button\" class=\"button-link danger remove-row\">削除</button></div>`;\r\n    attachImageHandlers(d);\r\n    // 新規行追加時、現在のスクリーニング状態に合わせてラベル表示を同期\r\n    syncScreeningPassUI();\r\n    return d;\r\n  }\r\n\r\n  function syncImagePreview(urlInput) {\r\n    // urlInput は display:flex の内側 div にある。.option-image-preview は外側 div の直下なので parentElement を経由する\r\n    const outerDiv = urlInput.closest('div[style]').parentElement;\r\n    const preview = outerDiv ? outerDiv.querySelector('.option-image-preview') : null;\r\n    const img = preview ? preview.querySelector('img') : null;\r\n    const url = urlInput.value.trim();\r\n    if (url && preview) {\r\n      if (img) img.src = url;\r\n      preview.style.display = '';\r\n    } else if (preview) {\r\n      preview.style.display = 'none';\r\n    }\r\n  }\r\n\r\n  function attachImageHandlers(container) {\r\n    container.querySelectorAll('.option-file-input').forEach(fileInput => {\r\n      // fileInput → <label> → <div style=\"display:flex\"> → outerDiv (style=\"flex:2\")\r\n      // outerDiv に .option-image-url と .option-image-preview の両方がある\r\n      const getOuterDiv = (el) => {\r\n        const inner = el.closest('div[style]');\r\n        return inner ? inner.parentElement : null;\r\n      };\r\n\r\n      const uploadFile = async (file) => {\r\n        const ALLOWED_TYPES = ['image/png', 'image/jpeg', 'image/jpg', 'image/webp'];\r\n        const MAX_BYTES = 5 * 1024 * 1024;\r\n        if (!ALLOWED_TYPES.includes(file.type)) {\r\n          alert('対応形式はPNG・JPEG・WebPのみです（選択: ' + (file.type || '不明') + '）');\r\n          return;\r\n        }\r\n        if (file.size > MAX_BYTES) {\r\n          alert('画像サイズは5MB以下にしてください（現在: ' + (file.size / 1024 / 1024).toFixed(1) + 'MB）');\r\n          return;\r\n        }\r\n        const outerDiv = getOuterDiv(fileInput);\r\n        if (!outerDiv) return;\r\n        const urlInput = outerDiv.querySelector('.option-image-url');\r\n        const preview  = outerDiv.querySelector('.option-image-preview');\r\n        const img      = preview ? preview.querySelector('img') : null;\r\n        const label    = fileInput.closest('label');\r\n        if (!urlInput) return;\r\n        if (label) label.textContent = '送信中...';\r\n        try {\r\n          const base64 = await new Promise((resolve, reject) => {\r\n            const reader = new FileReader();\r\n            reader.onload = () => resolve(reader.result.split(',')[1]);\r\n            reader.onerror = reject;\r\n            reader.readAsDataURL(file);\r\n          });\r\n          const resp = await fetch('/admin/api/upload/image', {\r\n            method: 'POST',\r\n            headers: { 'Content-Type': 'application/json' },\r\n            body: JSON.stringify({ data: base64, filename: file.name, mimeType: file.type }),\r\n          });\r\n          const json = await resp.json().catch(() => ({ error: 'サーバーエラー (HTTP ' + resp.status + ')' }));\r\n          if (!resp.ok || !json.url) throw new Error(json.error || 'Upload failed');\r\n          urlInput.value = json.url;\r\n          urlInput.dispatchEvent(new Event('input'));\r\n          if (img) img.src = json.url;\r\n          if (preview) preview.style.display = '';\r\n        } catch (err) {\r\n          alert('画像アップロード失敗: ' + err.message);\r\n        } finally {\r\n          if (label) {\r\n            label.innerHTML = 'ファイル選択<input type=\"file\" accept=\"image/png,image/jpeg,image/webp\" class=\"option-file-input\" hidden />';\r\n            const card = label.closest('.option-row') || label.closest('.matrix-row-card') || label.closest('.matrix-col-card') || label.closest('.question-text-image-card');\r\n            if (card) attachImageHandlers(card);\r\n          }\r\n        }\r\n      };\r\n\r\n      fileInput.addEventListener('change', async (e) => {\r\n        const file = e.target.files[0];\r\n        if (file) await uploadFile(file);\r\n      });\r\n\r\n      // ドラッグ＆ドロップ（外側 div への drag を受け付ける）\r\n      const outerDiv = getOuterDiv(fileInput);\r\n      if (outerDiv && !outerDiv.dataset.dropBound) {\r\n        outerDiv.dataset.dropBound = '1';\r\n        outerDiv.title = '画像をここにドロップできます';\r\n        outerDiv.addEventListener('dragenter', (e) => { e.preventDefault(); });\r\n        outerDiv.addEventListener('dragover', (e) => {\r\n          e.preventDefault();\r\n          outerDiv.style.outline = '2px dashed #2ca87a';\r\n          outerDiv.style.borderRadius = '6px';\r\n          outerDiv.style.background = 'rgba(44,168,122,0.06)';\r\n        });\r\n        outerDiv.addEventListener('dragleave', (e) => {\r\n          if (!outerDiv.contains(e.relatedTarget)) {\r\n            outerDiv.style.outline = '';\r\n            outerDiv.style.background = '';\r\n          }\r\n        });\r\n        outerDiv.addEventListener('drop', async (e) => {\r\n          e.preventDefault();\r\n          outerDiv.style.outline = '';\r\n          outerDiv.style.background = '';\r\n          const file = e.dataTransfer?.files?.[0];\r\n          if (file) await uploadFile(file);\r\n        });\r\n      }\r\n    });\r\n    container.querySelectorAll('.remove-image').forEach(btn => {\r\n      btn.addEventListener('click', () => {\r\n        const row = btn.closest('.option-row') || btn.closest('.matrix-row-card') || btn.closest('.matrix-col-card') || btn.closest('div');\r\n        const urlInput = row ? row.querySelector('.option-image-url') : null;\r\n        const preview = btn.closest('.option-image-preview');\r\n        if (urlInput) urlInput.value = '';\r\n        if (preview) preview.style.display = 'none';\r\n      });\r\n    });\r\n  }\r\n  // ----------------------------------------------------------------\r\n  // マトリクス行カードの追加・削除・hidden 同期\r\n  // ----------------------------------------------------------------\r\n  function makeMatrixRowCard(label = '', imageUrl = '', extraImages = '', description = '') {\r\n    const d = document.createElement('div');\r\n    d.className = 'row-card matrix-row-card';\r\n    d.innerHTML = `\r\n      <div style=\"display:flex;gap:8px;align-items:flex-start;flex-wrap:wrap;\">\r\n        <label style=\"flex:1;min-width:140px;\">行ラベル\r\n          <input type=\"text\" name=\"matrix_row_labels\" value=\"${escHtml(label)}\" placeholder=\"例: 満足度\" />\r\n        </label>\r\n        <div style=\"flex:2;min-width:200px;\">\r\n          <label>メイン画像URL（省略可）</label>\r\n          <div style=\"display:flex;gap:4px;align-items:center;\">\r\n            <input type=\"url\" name=\"matrix_row_image_urls\" class=\"option-image-url\"\r\n              value=\"${escHtml(imageUrl)}\" placeholder=\"https://...\"\r\n              style=\"flex:1;\" oninput=\"syncImagePreview(this)\" />\r\n            <label class=\"button-link secondary\" style=\"white-space:nowrap;cursor:pointer;\">ファイル選択\r\n              <input type=\"file\" accept=\"image/png,image/jpeg,image/webp\" class=\"option-file-input\" hidden />\r\n            </label>\r\n          </div>\r\n          <div class=\"option-image-preview\" style=\"margin-top:4px;${imageUrl ? '' : 'display:none;'}\">\r\n            <img src=\"${escHtml(imageUrl)}\" alt=\"preview\"\r\n              style=\"max-width:120px;max-height:80px;border-radius:4px;border:1px solid #ddd;\"\r\n              onerror=\"this.parentElement.style.display='none'\" />\r\n            <button type=\"button\" class=\"button-link danger remove-image\" style=\"font-size:12px;\">削除</button>\r\n          </div>\r\n          <label style=\"margin-top:6px;font-size:12px;color:#60726f;\">\r\n            追加画像URL（改行区切り・複数枚表示）\r\n            <textarea name=\"matrix_row_extra_image_urls\" rows=\"2\"\r\n              placeholder=\"https://...&#10;https://...\"\r\n              style=\"font-size:12px;\">${escHtml(extraImages)}</textarea>\r\n          </label>\r\n        </div>\r\n        <label style=\"flex:2;min-width:160px;\">補足説明（省略可）\r\n          <input type=\"text\" name=\"matrix_row_descriptions\" value=\"${escHtml(description)}\" placeholder=\"例: 商品名・説明\" />\r\n        </label>\r\n      </div>\r\n      <div class=\"inline-actions\"><button type=\"button\" class=\"button-link danger remove-matrix-row\">削除</button></div>`;\r\n    attachImageHandlers(d);\r\n    attachRemoveMatrixRow(d);\r\n    return d;\r\n  }\r\n\r\n  function attachRemoveMatrixRow(container) {\r\n    container.querySelectorAll('.remove-matrix-row').forEach(btn => {\r\n      btn.onclick = () => {\r\n        const rows = document.getElementById('matrixRowCards').querySelectorAll('.matrix-row-card');\r\n        if (rows.length <= 1) {\r\n          btn.closest('.matrix-row-card').querySelectorAll('input').forEach(f => f.value = '');\r\n          return;\r\n        }\r\n        btn.closest('.matrix-row-card').remove();\r\n        syncMatrixRowsHidden();\r\n      };\r\n    });\r\n  }\r\n\r\n  function syncMatrixRowsHidden() {\r\n    const labels = [...document.querySelectorAll('[name=\"matrix_row_labels\"]')]\r\n      .map(el => el.value.trim()).filter(Boolean);\r\n    const hidden = document.getElementById('matrixRowsHidden');\r\n    if (hidden) hidden.value = labels.join('\\n');\r\n  }\r\n\r\n  document.getElementById('addMatrixRow')?.addEventListener('click', () => {\r\n    const container = document.getElementById('matrixRowCards');\r\n    const card = makeMatrixRowCard();\r\n    container.appendChild(card);\r\n  });\r\n\r\n  // 既存行の削除ボタンをバインド\r\n  document.querySelectorAll('.matrix-row-card').forEach(card => attachRemoveMatrixRow(card));\r\n  document.querySelectorAll('#matrixRowCards .option-file-input').forEach(fi => attachImageHandlers(fi.closest('.matrix-row-card')));\r\n\r\n  // ----------------------------------------------------------------\r\n  // マトリクス列カードの追加・削除・hidden 同期\r\n  // ----------------------------------------------------------------\r\n  function makeMatrixColCard(label = '', imageUrl = '', extraImages = '', description = '') {\r\n    const d = document.createElement('div');\r\n    d.className = 'row-card matrix-col-card';\r\n    d.innerHTML = `\r\n      <div style=\"display:flex;gap:8px;align-items:flex-start;flex-wrap:wrap;\">\r\n        <label style=\"flex:1;min-width:140px;\">列ラベル\r\n          <input type=\"text\" name=\"matrix_col_labels\" value=\"${escHtml(label)}\" placeholder=\"例: そう思う\" />\r\n        </label>\r\n        <div style=\"flex:2;min-width:200px;\">\r\n          <label>メイン画像URL（省略可）</label>\r\n          <div style=\"display:flex;gap:4px;align-items:center;\">\r\n            <input type=\"url\" name=\"matrix_col_image_urls\" class=\"option-image-url\"\r\n              value=\"${escHtml(imageUrl)}\" placeholder=\"https://...\"\r\n              style=\"flex:1;\" oninput=\"syncImagePreview(this)\" />\r\n            <label class=\"button-link secondary\" style=\"white-space:nowrap;cursor:pointer;\">ファイル選択\r\n              <input type=\"file\" accept=\"image/png,image/jpeg,image/webp\" class=\"option-file-input\" hidden />\r\n            </label>\r\n          </div>\r\n          <div class=\"option-image-preview\" style=\"margin-top:4px;${imageUrl ? '' : 'display:none;'}\">\r\n            <img src=\"${escHtml(imageUrl)}\" alt=\"preview\"\r\n              style=\"max-width:120px;max-height:80px;border-radius:4px;border:1px solid #ddd;\"\r\n              onerror=\"this.parentElement.style.display='none'\" />\r\n            <button type=\"button\" class=\"button-link danger remove-image\" style=\"font-size:12px;\">削除</button>\r\n          </div>\r\n          <label style=\"margin-top:6px;font-size:12px;color:#60726f;\">\r\n            追加画像URL（改行区切り・複数枚表示）\r\n            <textarea name=\"matrix_col_extra_image_urls\" rows=\"2\"\r\n              placeholder=\"https://...&#10;https://...\"\r\n              style=\"font-size:12px;\">${escHtml(extraImages)}</textarea>\r\n          </label>\r\n        </div>\r\n        <label style=\"flex:2;min-width:160px;\">補足説明（省略可）\r\n          <input type=\"text\" name=\"matrix_col_descriptions\" value=\"${escHtml(description)}\" placeholder=\"例: ブランド名・商品説明\" />\r\n        </label>\r\n      </div>\r\n      <div class=\"inline-actions\"><button type=\"button\" class=\"button-link danger remove-matrix-col\">削除</button></div>`;\r\n    attachImageHandlers(d);\r\n    attachRemoveMatrixCol(d);\r\n    return d;\r\n  }\r\n\r\n  function attachRemoveMatrixCol(container) {\r\n    container.querySelectorAll('.remove-matrix-col').forEach(btn => {\r\n      btn.onclick = () => {\r\n        const cols = document.getElementById('matrixColCards').querySelectorAll('.matrix-col-card');\r\n        if (cols.length <= 1) {\r\n          btn.closest('.matrix-col-card').querySelectorAll('input').forEach(f => f.value = '');\r\n          return;\r\n        }\r\n        btn.closest('.matrix-col-card').remove();\r\n        syncMatrixColsHidden();\r\n      };\r\n    });\r\n  }\r\n\r\n  function syncMatrixColsHidden() {\r\n    const labels = [...document.querySelectorAll('[name=\"matrix_col_labels\"]')]\r\n      .map(el => el.value.trim()).filter(Boolean);\r\n    const hidden = document.getElementById('matrixColsHidden');\r\n    if (hidden) hidden.value = labels.join('\\n');\r\n  }\r\n\r\n  document.getElementById('addMatrixCol')?.addEventListener('click', () => {\r\n    const container = document.getElementById('matrixColCards');\r\n    const card = makeMatrixColCard();\r\n    container.appendChild(card);\r\n  });\r\n\r\n  // 既存列の削除ボタンをバインド\r\n  document.querySelectorAll('.matrix-col-card').forEach(card => attachRemoveMatrixCol(card));\r\n  document.querySelectorAll('#matrixColCards .option-file-input').forEach(fi => attachImageHandlers(fi.closest('.matrix-col-card')));\r\n\r\n  // 設問文画像カードのハンドラを初期化\r\n  const qtImgCard = document.querySelector('.question-text-image-card');\r\n  if (qtImgCard) attachImageHandlers(qtImgCard);\r\n\r\n  // フォーム送信前に matrix_rows / matrix_cols hidden を同期\r\n  document.querySelector('form').addEventListener('submit', () => {\r\n    syncMatrixRowsHidden();\r\n    syncMatrixColsHidden();\r\n  });\r\n\r\n  function makeExtractionRow(value = '') {\r\n    const d = document.createElement('div');\r\n    d.className = 'row-card extraction-row';\r\n    d.innerHTML = `<label>抽出したい項目\r\n      <input type=\"text\" name=\"extraction_items\" value=\"${escHtml(value)}\" placeholder=\"例: 種類 / 年齢\" />\r\n    </label><div class=\"inline-actions\"><button type=\"button\" class=\"button-link danger remove-row\">削除</button></div>`;\r\n    return d;\r\n  }\r\n  function makeBranchRow() {\r\n    const optHtml = nextQuestionOptions.map(o =>\r\n      `<option value=\"${escHtml(o.code)}\">${escHtml(o.code)} | ${escHtml(o.text)}</option>`\r\n    ).join('');\r\n    const d = document.createElement('div');\r\n    d.className = 'row-card branch-row';\r\n    d.innerHTML = `\r\n      <div class=\"form-grid\">\r\n        <label>判定元<select name=\"branch_source\" class=\"branch-source\">\r\n          <option value=\"answer\">回答そのもの</option>\r\n          <option value=\"extracted\">抽出項目</option>\r\n        </select></label>\r\n        <label>項目<select name=\"branch_field_label\" class=\"branch-field\">\r\n          <option value=\"\">回答そのもの</option>\r\n        </select></label>\r\n        <label>条件<select name=\"branch_operator\">\r\n          ${[\"equals\",\"includes\",\"any_of\",\"gte\",\"lte\"].map(op => `<option value=\"${op}\">${op}</option>`).join('')}\r\n        </select></label>\r\n        <label>値<input type=\"text\" name=\"branch_value\" placeholder=\"例: 1\" /></label>\r\n      </div>\r\n      <div class=\"form-grid\">\r\n        <label>遷移先<select name=\"branch_next\">\r\n          <option value=\"\">選択</option>${optHtml}\r\n        </select></label>\r\n      </div>\r\n      <div class=\"inline-actions\"><button type=\"button\" class=\"button-link danger remove-row\">削除</button></div>`;\r\n    return d;\r\n  }\r\n  function makeVisCondRow() {\r\n    const d = document.createElement('div');\r\n    d.className = 'row-card vis-cond-row';\r\n    d.innerHTML = `<label>条件式\r\n      <input type=\"text\" name=\"vis_condition_expr\" placeholder=\"例: q1=1 and q2=2\" class=\"font-mono\" />\r\n    </label><div class=\"inline-actions\"><button type=\"button\" class=\"button-link danger remove-row\">削除</button></div>`;\r\n    return d;\r\n  }\r\n  function makeAnsRow() {\r\n    const optHtml = nextQuestionOptions.map(o =>\r\n      `<option value=\"${escHtml(o.code)}\">${escHtml(o.code)} | ${escHtml(o.text)}</option>`\r\n    ).join('');\r\n    const d = document.createElement('div');\r\n    d.className = 'row-card ans-row';\r\n    d.innerHTML = `\r\n      <div class=\"form-grid\">\r\n        <label>参照元質問コード<select name=\"ans_source\"><option value=\"\">選択</option>${optHtml}</select></label>\r\n        <label>差し込み先<select name=\"ans_target\">\r\n          <option value=\"question_text\">設問文</option>\r\n          <option value=\"comment_top\">コメント上</option>\r\n          <option value=\"comment_bottom\">コメント下</option>\r\n        </select></label>\r\n      </div>\r\n      <div class=\"inline-actions\"><button type=\"button\" class=\"button-link danger remove-row\">削除</button></div>`;\r\n    return d;\r\n  }\r\n\r\n  const addTo = (containerId, makeRow) => {\r\n    const c = document.getElementById(containerId);\r\n    const row = makeRow();\r\n    c.appendChild(row);\r\n    attachRemoveRow(c);\r\n  };\r\n\r\n  ['optionRows','extractionRows','branchRows','visCondRows','ansRows'].forEach(id => {\r\n    const el = document.getElementById(id);\r\n    if (el) attachRemoveRow(el);\r\n  });\r\n\r\n  // 既存の選択肢行の画像ハンドラを初期化\r\n  const optionRowsEl = document.getElementById('optionRows');\r\n  if (optionRowsEl) attachImageHandlers(optionRowsEl);\r\n\r\n  // URL直入力の既存行にも syncImagePreview を紐付け\r\n  optionRowsEl && optionRowsEl.querySelectorAll('.option-image-url').forEach(inp => {\r\n    inp.addEventListener('input', () => syncImagePreview(inp));\r\n  });\r\n\r\n  document.getElementById('addOptionRow').onclick      = () => addTo('optionRows', makeOptionRow);\r\n  document.getElementById('addExtractionRow').onclick  = () => addTo('extractionRows', makeExtractionRow);\r\n  document.getElementById('addBranchRow').onclick      = () => addTo('branchRows', makeBranchRow);\r\n  document.getElementById('addVisCondRow').onclick     = () => addTo('visCondRows', makeVisCondRow);\r\n  document.getElementById('addAnsRow').onclick         = () => addTo('ansRows', makeAnsRow);\r\n\r\n  // ----------------------------------------------------------------\r\n  // 保存前にタグを自動生成して hidden フィールドへセット\r\n  //\r\n  // form.submit() は HTML5 の required 検証も submit イベントも通さないため使わない。\r\n  // 準備（タグ生成）が終わったらフラグを立てて requestSubmit() し直し、\r\n  // 2周目はネイティブ送信に任せる（isDirty リセットの submit リスナーも発火する）。\r\n  // ----------------------------------------------------------------\r\n  let submitPrepared = false;\r\n  let nativeSubmitStarted = false;\r\n  document.getElementById('mainForm').addEventListener('submit', async (e) => {\r\n    const form = e.currentTarget;\r\n    if (submitPrepared) { submitPrepared = false; nativeSubmitStarted = true; clearDraft(); return; }\r\n    e.preventDefault();\r\n\r\n    if (!form.checkValidity()) {\r\n      // どのタブにエラーがあるか分かるようにバッジを付け、最初の invalid のタブへ移動してから\r\n      // ブラウザ標準のエラーバブルを出す（非表示ペイン内のフィールドだとバブルが出ないため）。\r\n      updateTabErrorBadges();\r\n      const firstInvalid = form.querySelector(':invalid');\r\n      const pane = firstInvalid && firstInvalid.closest('.tab-pane');\r\n      if (pane) activateTab(pane.id.replace('tab-', ''));\r\n      form.reportValidity();\r\n      return;\r\n    }\r\n\r\n    // スクリーニング通過対象バリデーション\r\n    const isScreeningOn = document.getElementById('screeningCheck')?.checked ?? false;\r\n    const currentQType = document.getElementById('questionType')?.value ?? '';\r\n    if (isScreeningOn && SCREENING_CHOICE_TYPES_JS.includes(currentQType)) {\r\n      const passCount = [...document.querySelectorAll('.screening-pass-check')].filter(cb => cb.checked).length;\r\n      if (passCount === 0) {\r\n        updateTabErrorBadges(['answer']);\r\n        activateTab('answer');\r\n        alert('スクリーニング設問には、最低1つ以上の通過対象回答を設定してください。');\r\n        return;\r\n      }\r\n    }\r\n\r\n    // タグ生成の待ち時間中の二重送信を防ぐ\r\n    const submitButtons = [...form.querySelectorAll('button[type=\"submit\"], input[type=\"submit\"]')];\r\n    submitButtons.forEach(b => {\r\n      b.disabled = true;\r\n      if (b.tagName === 'BUTTON') { b.dataset.originalText = b.textContent; b.textContent = '保存中…'; }\r\n    });\r\n\r\n    const formData = collectTagFormData();\r\n    const hasTagInput = Object.values(formData).some(v => v === true || (typeof v === 'string' && v.trim() !== ''));\r\n    if (hasTagInput) {\r\n      try {\r\n        const res = await fetch('/admin/api/generate-tags', {\r\n          method: 'POST',\r\n          headers: { 'Content-Type': 'application/json' },\r\n          body: JSON.stringify(formData),\r\n        });\r\n        if (res.ok) {\r\n          const data = await res.json();\r\n          if (data.rawGenerated) {\r\n            document.getElementById('tagsRaw').value = data.rawGenerated;\r\n          }\r\n          if (data.parsed) {\r\n            document.getElementById('displayTagsParsedJson').value = JSON.stringify(data.parsed);\r\n          }\r\n        }\r\n      } catch(err) {\r\n        console.warn('tag auto-generate on submit failed', err);\r\n      }\r\n    }\r\n\r\n    // requestSubmit() は submit イベントの dispatch 中に呼んでも無視される。\r\n    // タグ入力があった場合は await 済みなのでフレームが抜けており発火するが、\r\n    // 入力が無いと同期のままここへ来るため 2 周目が発火せず、\r\n    // 何のエラーも出ないまま保存されない。常に 1 フレーム待ってから送る。\r\n    await new Promise(resolve => setTimeout(resolve, 0));\r\n\r\n    submitPrepared = true;\r\n    nativeSubmitStarted = false;\r\n    form.requestSubmit();\r\n    submitPrepared = false;\r\n    if (!nativeSubmitStarted) {\r\n      // 検証に弾かれて送信イベントが発火しなかった場合はボタンを戻す\r\n      submitButtons.forEach(b => {\r\n        b.disabled = false;\r\n        if (b.dataset.originalText) { b.textContent = b.dataset.originalText; delete b.dataset.originalText; }\r\n      });\r\n    }\r\n  });\r\n\r\n  // ----------------------------------------------------------------\r\n  // タグ解析（クライアントサイド簡易版）\r\n  // ----------------------------------------------------------------\r\n  document.getElementById('parseTagsBtn').onclick = async () => {\r\n    const raw = document.getElementById('tagsRaw').value;\r\n    const res = await fetch('/admin/api/parse-tags', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ raw, question_type: document.getElementById('questionType').value }),\r\n    });\r\n    if (!res.ok) { alert('タグ解析に失敗しました'); return; }\r\n    const data = await res.json();\r\n    showTagResult(data);\r\n  };\r\n\r\n  document.getElementById('generateTagsBtn').onclick = async () => {\r\n    const formData = collectTagFormData();\r\n    const res = await fetch('/admin/api/generate-tags', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify(formData),\r\n    });\r\n    if (!res.ok) { alert('タグ生成に失敗しました'); return; }\r\n    const data = await res.json();\r\n    document.getElementById('tagsRaw').value = data.rawGenerated || '';\r\n    showTagResult(data);\r\n  };\r\n\r\n  document.getElementById('clearTagsBtn').onclick = () => {\r\n    document.getElementById('tagsRaw').value = '';\r\n    document.getElementById('tagParseResult').classList.add('hidden');\r\n    document.getElementById('displayTagsParsedJson').value = '';\r\n  };\r\n\r\n  function showTagResult(data) {\r\n    const resultEl = document.getElementById('tagParseResult');\r\n    resultEl.classList.remove('hidden');\r\n\r\n    const errorList = document.getElementById('tagErrorItems');\r\n    const errorContainer = document.getElementById('tagErrorList');\r\n    const allIssues = [...(data.errors || []), ...(data.warnings || [])];\r\n    if (allIssues.length > 0) {\r\n      errorContainer.classList.remove('hidden');\r\n      errorList.innerHTML = allIssues.map(e =>\r\n        `<li class=\"${e.severity}\">[${e.severity}] ${escHtml(e.message)}</li>`\r\n      ).join('');\r\n    } else {\r\n      errorContainer.classList.add('hidden');\r\n      errorList.innerHTML = '';\r\n    }\r\n\r\n    document.getElementById('tagParsedPreview').textContent =\r\n      JSON.stringify(data.parsed, null, 2);\r\n    document.getElementById('tagGeneratedPreview').textContent =\r\n      data.rawGenerated || '';\r\n    document.getElementById('displayTagsParsedJson').value =\r\n      JSON.stringify(data.parsed);\r\n  }\r\n\r\n  function collectTagFormData() {\r\n    const f = name => {\r\n      const el = document.querySelector(`[name=\"${name}\"]`);\r\n      return el ? el.value : '';\r\n    };\r\n    const cb = name => {\r\n      const el = document.querySelector(`[name=\"${name}\"]`);\r\n      return el ? el.checked : false;\r\n    };\r\n    return {\r\n      tag_size: f('tag_size'), tag_min: f('tag_min'), tag_max: f('tag_max'),\r\n      tag_rows: f('tag_rows'), tag_cols: f('tag_cols'), tag_code: f('tag_code'),\r\n      tag_numeric: cb('tag_numeric'), tag_numeric_decimal: f('tag_numeric_decimal'),\r\n      tag_al: cb('tag_al'),\r\n      tag_type_year: cb('tag_type_year'), tag_type_jyear: cb('tag_type_jyear'),\r\n      tag_type_month: cb('tag_type_month'), tag_type_day: cb('tag_type_day'),\r\n      tag_norep: cb('tag_norep'), tag_fix: cb('tag_fix'), tag_br: cb('tag_br'),\r\n      tag_must: cb('tag_must'), tag_ex: cb('tag_ex'),\r\n      tag_len_op: f('tag_len_op'), tag_len_val: f('tag_len_val'),\r\n      tag_bf: f('tag_bf'), tag_af: f('tag_af'),\r\n    };\r\n  }\r\n\r\n  // ----------------------------------------------------------------\r\n  // プレビュー\r\n  // ----------------------------------------------------------------\r\n  const previewModal = document.getElementById('previewModal');\r\n  document.getElementById('previewBtn').onclick = () => {\r\n    const qText = document.querySelector('[name=\"question_text\"]').value;\r\n    const qType = document.getElementById('questionType').value;\r\n    const mode  = document.getElementById('previewMode').value;\r\n    const opts  = Array.from(document.querySelectorAll('[name=\"option_labels\"]')).map(el => el.value).filter(Boolean);\r\n    const commentTop    = document.querySelector('[name=\"comment_top\"]')?.value || '';\r\n    const commentBottom = document.querySelector('[name=\"comment_bottom\"]')?.value || '';\r\n    const matrixRows    = (document.querySelector('[name=\"matrix_rows\"]')?.value || '').split('\\n').filter(Boolean);\r\n    const matrixCols    = (document.querySelector('[name=\"matrix_cols\"]')?.value || '').split('\\n').filter(Boolean);\r\n\r\n    let html = buildPreviewHtml(qText, qType, mode, opts, commentTop, commentBottom, matrixRows, matrixCols);\r\n    document.getElementById('previewContent').innerHTML = html;\r\n    previewModal.style.display = 'flex';\r\n  };\r\n  document.getElementById('closePreview').onclick  = () => { previewModal.style.display = 'none'; };\r\n  document.getElementById('previewMode').onchange  = () => document.getElementById('previewBtn').click();\r\n\r\n  function buildPreviewHtml(qText, qType, mode, opts, commentTop, commentBottom, matrixRows, matrixCols) {\r\n    const wrapStyle = mode === 'interview_chat'\r\n      ? 'font-family:sans-serif;background:#f0f0f0;padding:16px;border-radius:12px;'\r\n      : 'font-family:sans-serif;padding:8px;';\r\n    let inner = '';\r\n\r\n    if (commentTop) inner += `<p style=\"font-size:12px;color:#60726f;margin:0 0 6px\">${escHtml(commentTop)}</p>`;\r\n\r\n    const bubble = mode === 'interview_chat'\r\n      ? `<div style=\"background:#fff;border-radius:12px;padding:12px;margin-bottom:10px;box-shadow:0 1px 4px rgba(0,0,0,.1);\">${escHtml(qText)}</div>`\r\n      : `<p style=\"font-weight:600;margin:0 0 10px\">${escHtml(qText)}</p>`;\r\n    inner += bubble;\r\n\r\n    if (commentBottom) inner += `<p style=\"font-size:12px;color:#60726f;margin:0 0 8px\">${escHtml(commentBottom)}</p>`;\r\n\r\n    if (['single_choice','text_with_image'].includes(qType) && opts.length > 0) {\r\n      inner += opts.map(o => `<label style=\"display:block;margin:4px 0;\"><input type=\"radio\" /> ${escHtml(o)}</label>`).join('');\r\n    } else if (qType === 'multi_choice' && opts.length > 0) {\r\n      inner += opts.map(o => `<label style=\"display:block;margin:4px 0;\"><input type=\"checkbox\" /> ${escHtml(o)}</label>`).join('');\r\n    } else if (['text','free_text_short','numeric'].includes(qType)) {\r\n      inner += `<input type=\"text\" style=\"width:100%;padding:8px;border:1px solid #ccc;border-radius:6px;\" placeholder=\"回答を入力...\" />`;\r\n    } else if (['free_text_long'].includes(qType)) {\r\n      inner += `<textarea rows=\"4\" style=\"width:100%;padding:8px;border:1px solid #ccc;border-radius:6px;\" placeholder=\"回答を入力...\"></textarea>`;\r\n    } else if (['scale'].includes(qType)) {\r\n      inner += `<input type=\"range\" min=\"1\" max=\"5\" style=\"width:100%\" />`;\r\n    } else if (['matrix_single','matrix_multi','matrix_mixed'].includes(qType)) {\r\n      if (matrixRows.length > 0 && matrixCols.length > 0) {\r\n        const isMulti = qType === 'matrix_multi';\r\n        inner += `<table style=\"width:100%;border-collapse:collapse;font-size:13px;\">\r\n          <tr><th style=\"padding:6px;border-bottom:1px solid #eee;text-align:left;\"></th>`;\r\n        for (const col of matrixCols) {\r\n          inner += `<th style=\"padding:6px;border-bottom:1px solid #eee;text-align:center;\">${escHtml(col)}</th>`;\r\n        }\r\n        inner += `</tr>`;\r\n        for (const row of matrixRows) {\r\n          inner += `<tr><td style=\"padding:6px;border-bottom:1px solid #eee;\">${escHtml(row)}</td>`;\r\n          for (let ci = 0; ci < matrixCols.length; ci++) {\r\n            inner += `<td style=\"padding:6px;border-bottom:1px solid #eee;text-align:center;\">\r\n              <input type=\"${isMulti ? 'checkbox' : 'radio'}\" name=\"prev_row_${escHtml(row)}\" />\r\n            </td>`;\r\n          }\r\n          inner += `</tr>`;\r\n        }\r\n        inner += `</table>`;\r\n      } else {\r\n        inner += `<p style=\"font-size:12px;color:#888;\">[マトリクス - 行・列を「2. 回答形式」タブで設定してください]</p>`;\r\n      }\r\n    }\r\n\r\n    if (mode === 'interview_chat') {\r\n      inner += `<div style=\"margin-top:8px;\">\r\n        <input type=\"text\" placeholder=\"返信する...\" style=\"width:calc(100% - 60px);padding:8px;border:1px solid #ccc;border-radius:20px;\" />\r\n        <button style=\"padding:8px 12px;background:#2ca87a;color:#fff;border:none;border-radius:20px;margin-left:4px;\">送信</button>\r\n      </div>`;\r\n    } else {\r\n      inner += `<div style=\"margin-top:16px;text-align:right;\">\r\n        <button style=\"padding:8px 24px;background:#2ca87a;color:#fff;border:none;border-radius:8px;\">次へ</button>\r\n      </div>`;\r\n    }\r\n\r\n    return `<div style=\"${wrapStyle}\">${inner}</div>`;\r\n  }\r\n\r\n  // ----------------------------------------------------------------\r\n  // util\r\n  // ----------------------------------------------------------------\r\n  function escHtml(str) {\r\n    return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');\r\n  }\r\n\r\n  syncTypeVisibility();\r\n\r\n  // ----------------------------------------------------------------\r\n  // 未保存変更検知 + 設問ナビゲーション\r\n  // ----------------------------------------------------------------\r\n  let isDirty = false;\r\n  const mainForm = document.getElementById('mainForm');\r\n  mainForm.addEventListener('change', () => { isDirty = true; refreshTabErrorBadges(); scheduleDraftSave(); });\r\n  mainForm.addEventListener('input', () => { isDirty = true; refreshTabErrorBadges(); scheduleDraftSave(); });\r\n  mainForm.addEventListener('submit', () => { isDirty = false; });\r\n\r\n  // タブ閉じ・リロード・素の a タグ遷移（「一覧へ戻る」を含む）での全損を防ぐ。\r\n  // navigateTo() 経由の遷移は confirm 後に isDirty=false になるので二重ダイアログにならない。\r\n  window.addEventListener('beforeunload', (e) => {\r\n    if (!isDirty) return;\r\n    saveDraftNow();\r\n    e.preventDefault();\r\n    e.returnValue = '';\r\n  });\r\n\r\n  function navigateTo(href) {\r\n    if (isDirty) {\r\n      if (!confirm('未保存の変更があります。保存せずに移動しますか？')) return;\r\n      isDirty = false;\r\n    }\r\n    window.location.href = href;\r\n  }\r\n\r\n  document.querySelectorAll('.nav-question-btn').forEach(btn => {\r\n    btn.addEventListener('click', () => navigateTo(btn.dataset.href));\r\n  });\r\n\r\n  // キーボードナビゲーション（←→キー、テキスト入力中は無効）\r\n  document.addEventListener('keydown', (e) => {\r\n    const tag = document.activeElement ? document.activeElement.tagName : '';\r\n    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;\r\n    if (e.key === 'ArrowLeft') {\r\n      const btn = document.querySelector('.nav-question-btn[data-nav-key=\"prev\"]');\r\n      if (btn) btn.click();\r\n    } else if (e.key === 'ArrowRight') {\r\n      const btn = document.querySelector('.nav-question-btn[data-nav-key=\"next\"]');\r\n      if (btn) btn.click();\r\n    }\r\n  });\r\n\r\n  // ----------------------------------------------------------------\r\n  // タブエラーバッジ\r\n  // .tab-btn.has-error / .err-badge の CSS は定義済みだったが、付与する JS が\r\n  // 無かった（＝設計はあるが未実装）。開いた直後から赤くならないよう、\r\n  // 最初の送信試行で validationAttempted が立ってから input 連動で更新する。\r\n  // ----------------------------------------------------------------\r\n  let validationAttempted = false;\r\n  function updateTabErrorBadges(extraTabs = []) {\r\n    validationAttempted = true;\r\n    document.querySelectorAll('.tab-btn').forEach(btn => {\r\n      const pane = document.getElementById('tab-' + btn.dataset.tab);\r\n      if (!pane) return;\r\n      const invalidCount = pane.querySelectorAll('input:invalid, select:invalid, textarea:invalid').length;\r\n      const flagged = invalidCount > 0 || extraTabs.includes(btn.dataset.tab);\r\n      let badge = btn.querySelector('.err-badge');\r\n      if (flagged) {\r\n        btn.classList.add('has-error');\r\n        if (!badge) { badge = document.createElement('span'); badge.className = 'err-badge'; btn.appendChild(badge); }\r\n        badge.textContent = invalidCount > 0 ? String(invalidCount) : '!';\r\n      } else {\r\n        btn.classList.remove('has-error');\r\n        if (badge) badge.remove();\r\n      }\r\n    });\r\n  }\r\n  function refreshTabErrorBadges() { if (validationAttempted) updateTabErrorBadges(); }\r\n\r\n  // ----------------------------------------------------------------\r\n  // 下書き自動保存（localStorage）\r\n  // セッション切れ・タブクラッシュ・誤遷移での全損対策。入力のたびに\r\n  // デバウンス保存し、保存成功（ネイティブ送信開始）で破棄する。\r\n  // 制約: 画像ファイルとマトリクスの行・列カードは復元対象外\r\n  // （マトリクスは送信時にカードから hidden へ再同期されるため、復元しても上書きされる）。\r\n  // ----------------------------------------------------------------\r\n  const DRAFT_KEY = 'hibi:formV3:draft:")
    ; __append(escapeFn( project.id ))
