    ; __append("';\r\n  const DYNAMIC_ROW_BUTTONS = {\r\n    optionRows: 'addOptionRow',\r\n    extractionRows: 'addExtractionRow',\r\n    branchRows: 'addBranchRow',\r\n    visCondRows: 'addVisCondRow',\r\n    ansRows: 'addAnsRow'\r\n  };\r\n  let draftTimer = null;\r\n\r\n  function collectDraft() {\r\n    const fields = [];\r\n    mainForm.querySelectorAll('input[name], select[name], textarea[name]').forEach(el => {\r\n      if (el.type === 'file' || el.type === 'submit' || el.type === 'button') return;\r\n      if (el.name === 'matrix_rows' || el.name === 'matrix_cols') return;\r\n      fields.push({\r\n        name: el.name,\r\n        value: el.value,\r\n        checked: (el.type === 'checkbox' || el.type === 'radio') ? el.checked : undefined\r\n      });\r\n    });\r\n    const rowCounts = {};\r\n    Object.keys(DYNAMIC_ROW_BUTTONS).forEach(id => {\r\n      const c = document.getElementById(id);\r\n      if (c) rowCounts[id] = c.children.length;\r\n    });\r\n    return { savedAt: new Date().toISOString(), fields, rowCounts };\r\n  }\r\n\r\n  function saveDraftNow() {\r\n    if (!isDirty) return;\r\n    try {\r\n      localStorage.setItem(DRAFT_KEY, JSON.stringify(collectDraft()));\r\n    } catch (err) { /* private mode / 容量超過では黙って諦める（本保存には影響しない） */ }\r\n  }\r\n  function scheduleDraftSave() {\r\n    if (draftTimer) clearTimeout(draftTimer);\r\n    draftTimer = setTimeout(saveDraftNow, 800);\r\n  }\r\n  function clearDraft() {\r\n    try { localStorage.removeItem(DRAFT_KEY); } catch (err) { /* noop */ }\r\n  }\r\n\r\n  function restoreDraft(draft) {\r\n    // 1) 動的行の本数を合わせる（不足分だけ既存の追加ボタンで生成。多い分は触らない）\r\n    Object.entries(DYNAMIC_ROW_BUTTONS).forEach(([containerId, btnId]) => {\r\n      const c = document.getElementById(containerId);\r\n      const btn = document.getElementById(btnId);\r\n      const want = (draft.rowCounts && draft.rowCounts[containerId]) || 0;\r\n      if (!c || !btn) return;\r\n      let guard = 0;\r\n      while (c.children.length < want && guard++ < 100) btn.click();\r\n    });\r\n\r\n    // 2) name ごとに DOM 順で値を流し込む\r\n    const groups = {};\r\n    (draft.fields || []).forEach(f => { (groups[f.name] = groups[f.name] || []).push(f); });\r\n    Object.entries(groups).forEach(([name, saved]) => {\r\n      const els = [...mainForm.querySelectorAll('[name=\"' + CSS.escape(name) + '\"]')];\r\n      if (els.length === 0) return;\r\n      if (els[0].type === 'radio') {\r\n        const checkedValue = (saved.find(f => f.checked) || {}).value;\r\n        els.forEach(el => { el.checked = (el.value === checkedValue); });\r\n        const sel = els.find(el => el.checked);\r\n        if (sel) sel.dispatchEvent(new Event('change', { bubbles: true }));\r\n        return;\r\n      }\r\n      els.forEach((el, i) => {\r\n        const f = saved[i];\r\n        if (!f) return;\r\n        if (el.type === 'checkbox') {\r\n          el.checked = !!f.checked;\r\n        } else {\r\n          el.value = f.value;\r\n        }\r\n        el.dispatchEvent(new Event('change', { bubbles: true }));\r\n      });\r\n    });\r\n\r\n    // 3) 値に依存する表示状態を再同期\r\n    try { syncTypeVisibility(); } catch (err) { /* noop */ }\r\n    try { syncScreeningPassUI(); } catch (err) { /* noop */ }\r\n    isDirty = true;\r\n  }\r\n\r\n  // 復元バナー。下書きがあるときだけフォーム先頭に出す。\r\n  (function initDraftRestore() {\r\n    let draft = null;\r\n    try {\r\n      const raw = localStorage.getItem(DRAFT_KEY);\r\n      if (raw) draft = JSON.parse(raw);\r\n    } catch (err) { /* 壊れた下書きは無視 */ }\r\n    if (!draft || !Array.isArray(draft.fields) || draft.fields.length === 0) return;\r\n\r\n    const banner = document.createElement('section');\r\n    banner.className = 'card subtle-card';\r\n    banner.style.cssText = 'background:#fdf6ec;border-left:4px solid #d99b2b;display:flex;gap:12px;align-items:center;flex-wrap:wrap';\r\n    const savedAt = draft.savedAt ? new Date(draft.savedAt).toLocaleString('ja-JP') : '';\r\n    const label = document.createElement('span');\r\n    label.style.fontSize = '13px';\r\n    label.textContent = '保存されていない下書きがあります' + (savedAt ? '（' + savedAt + ' 時点）' : '') + '。';\r\n    const restoreBtn = document.createElement('button');\r\n    restoreBtn.type = 'button';\r\n    restoreBtn.className = 'button-link secondary';\r\n    restoreBtn.textContent = '下書きを復元する';\r\n    restoreBtn.addEventListener('click', () => { restoreDraft(draft); banner.remove(); });\r\n    const discardBtn = document.createElement('button');\r\n    discardBtn.type = 'button';\r\n    discardBtn.className = 'button-link danger';\r\n    discardBtn.textContent = '破棄する';\r\n    discardBtn.addEventListener('click', () => { clearDraft(); banner.remove(); });\r\n    banner.appendChild(label);\r\n    banner.appendChild(restoreBtn);\r\n    banner.appendChild(discardBtn);\r\n    mainForm.insertBefore(banner, mainForm.firstChild);\r\n  })();\r\n})();\r\n</script>\r\n\r\n")
