    ; __append("'></div>\n\n    <script>\n    (() => {\n      'use strict';\n      const d = JSON.parse(document.getElementById('initial-data').dataset.json || '{}');\n      const {\n        liffId, interactionsDataUrl, savedDataUrl,\n        surveyBaseUrl, projectDetailBaseUrl, projectsUrl\n      } = d;\n\n      let idToken = null;\n\n      function esc(v) {\n        return String(v ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;');\n      }\n      function fmtDate(iso) {\n        if (!iso) return '';\n        const dt = new Date(iso);\n        return `${dt.getMonth() + 1}月${dt.getDate()}日`;\n      }\n      function minsLabel(m) {\n        return typeof m === 'number' && m > 0 ? `約${m}分` : '';\n      }\n\n      /** 「いま回答できる」1件。中断中は残りが見えるよう文言を変える。 */\n      function answerableCard(a) {\n        const resuming = a.status === 'started';\n        const bits = [\n          resuming ? '回答が途中です' : '当選・未回答',\n          minsLabel(a.estimated_minutes),\n          a.reward_points ? `${Number(a.reward_points).toLocaleString()}pt` : ''\n        ].filter(Boolean);\n        return `\n          <div class=\"hb-st\">\n            <div class=\"ic resume\">${resuming ? '▶' : '✎'}</div>\n            <div class=\"bd\">\n              <h4>${esc(a.title)}</h4>\n              <div class=\"sub\">${esc(bits.join(' · '))}</div>\n              <a class=\"cta\" href=\"${esc(surveyBaseUrl)}/${esc(a.assignment_id)}\"\n                 data-answer-id=\"${esc(a.assignment_id)}\">\n                ${resuming ? '続きから回答する' : '回答をはじめる ⚡'}\n              </a>\n            </div>\n          </div>`;\n      }\n\n      function savedCard(p) {\n        const bits = [minsLabel(p.estimated_minutes), p.reward_points ? `${Number(p.reward_points).toLocaleString()}pt` : '']\n          .filter(Boolean);\n        return `\n          <a class=\"hb-st\" href=\"${esc(projectDetailBaseUrl)}/${esc(p.id)}\" data-saved-id=\"${esc(p.id)}\">\n            <div class=\"ic save\">★</div>\n            <div class=\"bd\">\n              <h4>${esc(p.title)}</h4>\n              <div class=\"sub\">${esc(bits.join(' · ')) || '保存した案件'}</div>\n            </div>\n            ${p.is_active ? '' : '<span class=\"pill ng\">募集終了</span>'}\n          </a>`;\n      }\n\n      function waitingCard(a) {\n        return `\n          <div class=\"hb-st\">\n            <div class=\"ic wait\">⏳</div>\n            <div class=\"bd\">\n              <h4>${esc(a.title)}</h4>\n              <div class=\"sub\">${esc(fmtDate(a.applied_at))} 応募 · 結果はLINEでお知らせします</div>\n            </div>\n            <span class=\"pill wait\">選考中</span>\n          </div>`;\n      }\n\n      /** 終了群。落選・対象外・完了・期限切れをまとめて静かに置く。 */\n      function finishedCard(item) {\n        const LABEL = {\n          rejected:  '落選',\n          completed: '回答済み',\n          expired:   '期限切れ',\n          cancelled: '取消',\n        };\n        const label = LABEL[item.status] || '終了';\n        const when = item.decided_at || item.completed_at || item.applied_at;\n        return `\n          <div class=\"hb-st\">\n            <div class=\"ic ng\">—</div>\n            <div class=\"bd\">\n              <h4>${esc(item.title)}</h4>\n              <div class=\"sub\">${esc(when ? fmtDate(when) : '')}</div>\n            </div>\n            <span class=\"pill ng\">${esc(label)}</span>\n          </div>`;\n      }\n\n      function render(inter, saved) {\n        const el = document.getElementById('content');\n        document.getElementById('loading-overlay').style.display = 'none';\n        el.style.display = '';\n\n        // 「いま回答できる」= 中断中を先に、次に当選未回答。\n        // 途中まで答えたものを最優先で拾えるようにする（取りこぼしが最も惜しいため）。\n        const answerable = [...(inter.in_progress || []), ...(inter.pending || [])];\n        const waiting    = (inter.applications || []).filter(a => a.status === 'applied');\n        const finished   = [\n          ...(inter.applications || []).filter(a => a.status === 'rejected'),\n          ...(inter.completed || []),\n        ];\n        const savedList  = saved.projects || [];\n\n        const parts = [];\n\n        if (answerable.length > 0) {\n          parts.push(`<div class=\"hb-grp strong\"><span>▶ いま回答できる</span><span class=\"cnt\">${answerable.length}件</span></div>`);\n          parts.push(answerable.map(answerableCard).join(''));\n        }\n\n        if (savedList.length > 0) {\n          parts.push(`<div class=\"hb-grp\"><span>★ 保存した案件</span><span class=\"cnt\">${savedList.length}件</span></div>`);\n          parts.push(savedList.map(savedCard).join(''));\n        }\n\n        if (waiting.length > 0) {\n          parts.push(`<div class=\"hb-grp\"><span>⏳ 結果を待っている</span><span class=\"cnt\">${waiting.length}件</span></div>`);\n          parts.push(waiting.map(waitingCard).join(''));\n        }\n\n        if (finished.length > 0) {\n          parts.push(`<div class=\"hb-grp\"><span>— 終了した応募</span><span class=\"cnt\">${finished.length}件</span></div>`);\n          parts.push(finished.map(finishedCard).join(''));\n        }\n\n        // 案件が1件も無い状態。今日の1問・スワイプは上に出ているので、\n        // 「何もない」ではなく「案件を探す」導線を出す。\n        if (parts.length === 0) {\n          parts.push(`\n            <div class=\"hb-none\">\n              まだ応募した案件はありません。<br>\n              気になる案件を探してみましょう。\n              <a class=\"go\" href=\"${esc(projectsUrl)}\">案件を探す</a>\n            </div>`);\n        }\n\n        el.innerHTML = parts.join('');\n\n        // 回答開始・再開のタップを計測（ナビ改善の効果測定に使う）。\n        el.querySelectorAll('[data-answer-id]').forEach(a => {\n          a.addEventListener('click', () => {\n            if (window.HbTrack) {\n              window.HbTrack.push('apply_tap', 'answer:' + a.dataset.answerId, null);\n              window.HbTrack.flush();\n            }\n          });\n        });\n        el.querySelectorAll('[data-saved-id]').forEach(a => {\n          a.addEventListener('click', () => {\n            if (window.HbTrack) {\n              window.HbTrack.push('card_tap', 'saved:' + a.dataset.savedId, null);\n              window.HbTrack.flush();\n            }\n          });\n        });\n      }\n\n      async function load() {\n        try {\n          const token = await LiffAuth.initLiffOrWebAuth(liffId);\n          if (!token) return;\n          idToken = token;\n\n          const headers = { Authorization: `Bearer ${idToken}` };\n\n          // 今日の1問・ついでスワイプは案件一覧の取得をブロックしない\n          // （失敗してもカードを出さないだけ）。\n          const onPointGained = (result) => {\n            try {\n              if (window.RankCelebration) RankCelebration.maybePlay(null, result.pointStatus);\n            } catch (e) { console.error('rank celebration failed', e); }\n          };\n          DailyToday.mount({ idToken, url: d.dailyTodayUrl, onAnswered: onPointGained });\n          if (window.PoolSwipe) {\n            PoolSwipe.mount({ idToken, url: d.poolQuestionsTodayUrl, onAnswered: onPointGained });\n          }\n\n          // 既存の2エンドポイントを並列で取り、クライアントで束ねる（新規APIを作らない）。\n          // 片方が落ちても、もう片方は描けるようにする。\n          const [interRes, savedRes] = await Promise.allSettled([\n            fetch(interactionsDataUrl, { headers }).then(r => r.json()),\n            fetch(savedDataUrl, { headers }).then(r => r.json()),\n          ]);\n\n          const inter = interRes.status === 'fulfilled' ? interRes.value : {};\n          const saved = savedRes.status === 'fulfilled' ? savedRes.value : {};\n          render(inter, saved);\n\n          // バッジはいま取得したデータから直接更新する（同じ内容を再取得しない）。\n          const el = document.getElementById('nav-answer-badge');\n          if (el) {\n            const n = (inter.in_progress || []).length + (inter.pending || []).length;\n            if (n > 0) { el.textContent = n > 99 ? '99+' : String(n); el.hidden = false; }\n            else { el.hidden = true; }\n          }\n        } catch (err) {\n          console.error('load failed', err);\n          document.getElementById('loading-overlay').style.display = 'none';\n          const el = document.getElementById('content');\n          el.style.display = '';\n          el.innerHTML = '<div class=\"hb-none\">読み込みに失敗しました。時間をおいて開き直してください。</div>';\n        }\n      }\n\n      load();\n    })();\n    </script>\n  </body>\n</html>\n")
