    ; __append("'></div>\n\n    <script>\n    (() => {\n      'use strict';\n      const d = JSON.parse(document.getElementById('initial-data').dataset.json || '{}');\n      const { liffId, interactionsDataUrl, surveyBaseUrl, projectsUrl } = d;\n\n      let idToken = null;\n      let currentTab = 'applications';\n\n      function esc(v) {\n        return String(v ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;');\n      }\n      function fmtDate(iso) {\n        if (!iso) return '';\n        const date = new Date(iso);\n        return `${date.getMonth()+1}/${date.getDate()}`;\n      }\n\n      const asgBadge = {\n        assigned:  { label: '当選・未回答', cls: 'win' },\n        sent:      { label: '当選・未回答', cls: 'win' },\n        opened:    { label: '未回答',       cls: 'win' },\n        started:   { label: '回答中',       cls: 'doing' },\n        completed: { label: '完了',         cls: 'done' },\n        expired:   { label: '期限切れ',     cls: 'lose' },\n        cancelled: { label: 'キャンセル',   cls: 'lose' },\n      };\n\n      function emptyState(msg) {\n        return `<div class=\"hb-empty\"><div class=\"icon\">📋</div><p>${esc(msg)}</p><a class=\"hb-btn ghost hb-mt16\" href=\"${esc(projectsUrl)}\" style=\"max-width:240px;margin-left:auto;margin-right:auto\">案件を探す</a></div>`;\n      }\n\n      function renderApplications(items) {\n        const el = document.getElementById('tab-applications');\n        if (!items.length) { el.innerHTML = emptyState('応募中の案件はありません'); return; }\n        el.innerHTML = items.map(a => `\n          <div class=\"item\">\n            <span class=\"hb-status ${a.status === 'applied' ? 'wait' : 'lose'}\">${a.status === 'applied' ? '選考中' : '落選'}</span>\n            <h3>${esc(a.title)}</h3>\n            <div class=\"sub\">\n              <span>${fmtDate(a.applied_at)} 応募</span>\n              ${a.reward_points ? `<span class=\"pt\">${a.reward_points.toLocaleString()}pt</span>` : ''}\n            </div>\n            ${a.status === 'applied' ? `\n            <div class=\"act\"><button class=\"hb-btn sub withdraw-btn\" data-project=\"${esc(a.project_id)}\" style=\"font-size:12.5px;padding:9px\">応募を取り消す</button></div>` : ''}\n          </div>`).join('');\n\n        el.querySelectorAll('.withdraw-btn').forEach(btn => {\n          btn.addEventListener('click', async () => {\n            if (!confirm('応募を取り消しますか？')) return;\n            try {\n              const res = await fetch(`/liff/projects/${btn.dataset.project}/withdraw`, {\n                method: 'POST', headers: { Authorization: `Bearer ${idToken}` }\n              });\n              const json = await res.json();\n              if (!json.ok) { alert(json.error || '取り消せませんでした。'); return; }\n              void load();\n            } catch { alert('通信に失敗しました。'); }\n          });\n        });\n      }\n\n      function renderAssignments(name, items, emptyMsg) {\n        const el = document.getElementById(`tab-${name}`);\n        if (!items.length) { el.innerHTML = emptyState(emptyMsg); return; }\n        el.innerHTML = items.map(a => {\n          const b = asgBadge[a.status] || { label: a.status, cls: 'done' };\n          const answerable = ['assigned', 'sent', 'opened', 'started'].includes(a.status);\n          return `\n          <div class=\"item ${answerable ? 'hot' : ''}\" ${!answerable ? 'style=\"opacity:.75\"' : ''}>\n            <span class=\"hb-status ${b.cls}\">${b.label}</span>\n            <h3>${esc(a.title)}</h3>\n            <div class=\"sub\">\n              ${a.estimated_minutes ? `<span>約${a.estimated_minutes}分</span>` : ''}\n              ${a.deadline ? `<span>期限 ${fmtDate(a.deadline)}</span>` : ''}\n              ${a.completed_at ? `<span>${fmtDate(a.completed_at)} 完了</span>` : ''}\n              ${a.reward_points ? `<span class=\"pt\">${a.status === 'completed' ? '+' : ''}${a.reward_points.toLocaleString()}pt</span>` : ''}\n            </div>\n            ${answerable ? `\n            <div class=\"act\"><a class=\"hb-btn primary\" href=\"${esc(surveyBaseUrl)}/${esc(a.assignment_id)}\" style=\"display:block;text-align:center;text-decoration:none\">${a.status === 'started' ? '続きから回答する' : '回答をはじめる ⚡'}</a></div>` : ''}\n          </div>`;\n        }).join('');\n      }\n\n      function renderAll(data) {\n        document.getElementById('loading-overlay').style.display = 'none';\n        const apps = data.applications || [];\n        renderApplications(apps);\n        renderAssignments('pending', data.pending || [], '実施予定の案件はありません');\n        renderAssignments('in_progress', data.in_progress || [], '回答中の案件はありません');\n        renderAssignments('completed', data.completed || [], '完了した案件はまだありません');\n        setCnt('applications', apps.filter(a => a.status === 'applied').length);\n        setCnt('pending', (data.pending || []).length);\n        setCnt('in_progress', (data.in_progress || []).length);\n        setCnt('completed', (data.completed || []).length);\n        showTab(currentTab);\n      }\n      function setCnt(name, n) {\n        document.getElementById(`cnt-${name}`).textContent = n > 0 ? String(n) : '';\n      }\n      function showTab(name) {\n        currentTab = name;\n        document.querySelectorAll('.hb-tab').forEach(t => t.classList.remove('on'));\n        document.querySelectorAll('.tab-content').forEach(c => c.style.display = 'none');\n        document.querySelector(`.hb-tab[data-tab=\"${name}\"]`)?.classList.add('on');\n        document.getElementById(`tab-${name}`).style.display = 'block';\n      }\n\n      document.getElementById('tab-bar').addEventListener('click', e => {\n        const tab = e.target.closest('.hb-tab');\n        if (tab) showTab(tab.dataset.tab);\n      });\n\n      async function load() {\n        try {\n          const token = await LiffAuth.initLiffOrWebAuth(liffId);\n          if (!token) return;\n          idToken = token;\n\n          // 今日の1問はこの画面の表示をブロックしない（失敗してもカードを出さないだけ）。\n          DailyToday.mount({ idToken });\n\n          const res = await fetch(interactionsDataUrl, { headers: { Authorization: `Bearer ${idToken}` } });\n          const data = await res.json();\n          renderAll(data);\n\n          // 「回答する」タブのバッジ。同じデータを持っているので再取得しない。\n          const badge = document.getElementById('nav-answer-badge');\n          if (badge) {\n            const n = (data.in_progress || []).length + (data.pending || []).length;\n            if (n > 0) { badge.textContent = n > 99 ? '99+' : String(n); badge.hidden = false; }\n            else { badge.hidden = true; }\n          }\n        } catch (err) {\n          document.getElementById('loading-overlay').style.display = 'none';\n          const el = document.getElementById('tab-applications');\n          el.style.display = 'block';\n          el.innerHTML = `<div class=\"hb-empty\"><div class=\"icon\">⚠️</div><p>${esc(err.message || '読み込みに失敗しました')}</p></div>`;\n        }\n      }\n\n      void load();\n    })();\n    </script>\n  </body>\n</html>\n")
