    ; __append("'></div>\n    <script>\n    (function () {\n      const initialData = JSON.parse(document.getElementById(\"initial-data\").dataset.json || \"{}\");\n      if (!initialData.missionId) return;\n      let idToken = null;\n\n      const esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) =>\n        ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]));\n      const $ = (id) => document.getElementById(id);\n\n      function renderStages(data) {\n        const box = $(\"prizes\");\n        box.hidden = false;\n        // 上の段を先頭に（下から上へ上る見た目は行の並びで表現）\n        const rows = [...data.stages].sort((a, b) => b.stageNo - a.stageNo).map((s) => {\n          const cls = s.state === \"done\" ? \"done\" : s.state === \"current\" ? \"current\" : \"lock\";\n          const mark = s.state === \"done\" ? \"✓\" : s.stageNo;\n          const cond = `${s.needAnswers}問 こたえる`;\n          const or = `または ${s.needInvites}人 さそう`;\n          const value = s.rewardPoints === null ? \"???\" : `${s.rewardPoints}pt`;\n          const sub = s.state === \"done\" ? \"受け取りずみ\" : or;\n          const glow = data.newlyAwarded.includes(s.stageNo) ? \" celebrate\" : \"\";\n          return `<div class=\"pz ${cls}${glow}\">\n            <div class=\"no\">${mark}</div>\n            <div class=\"t\"><div class=\"c\">${esc(cond)}</div><div class=\"s\">${esc(sub)}</div></div>\n            <div class=\"v\">${esc(value)}</div>\n          </div>`;\n        });\n        box.innerHTML = rows.join(\"\");\n      }\n\n      function renderGauge(g) {\n        if (!g) return; // 分母が無ければ帯ごと出さない（D-14）\n        const pct = Math.min(100, Math.round((g.current / g.target) * 100));\n        const dl = g.deadline\n          ? `のこり ${Math.max(0, Math.ceil((Date.parse(g.deadline) - Date.now()) / 86400000))}日` : \"\";\n        $(\"gauge-slot\").innerHTML = `<div class=\"gauge\">\n          <div class=\"top\"><span class=\"n\">${g.current}</span><span class=\"of\">/ ${g.target}人</span>\n          <span class=\"dl\">${esc(dl)}</span></div>\n          <div class=\"bar\"><i style=\"width:${pct}%\"></i></div></div>`;\n      }\n\n      const ROOM_EMOJI = [\"🍙\", \"🏠\", \"💼\", \"🎈\", \"🧺\", \"☕\"];\n      const projectsUrl = (cat) => `/liff/projects?category=${encodeURIComponent(cat)}`;\n\n      function renderRooms(rooms) {\n        if (!rooms || rooms.length === 0) return; // 部屋が無ければセクションごと出さない\n        const cards = rooms.map((r, i) => {\n          const dotsTotal = Math.min(5, r.total);\n          const dotsOn = r.total <= 5 ? r.answered\n            : Math.min(dotsTotal, Math.round((r.answered / r.total) * dotsTotal));\n          const dots = Array.from({ length: dotsTotal }, (_, d) =>\n            `<i class=\"${d < dotsOn ? \"on\" : \"\"}\"></i>`).join(\"\");\n          const mt = r.cleared ? \"ぜんぶ こたえた\" : `${r.remaining}件 のこってる`;\n          return `<a class=\"room ${r.cleared ? \"cleared\" : \"\"}\" href=\"${projectsUrl(r.category)}\">\n            <div class=\"ic\">${ROOM_EMOJI[i % ROOM_EMOJI.length]}</div>\n            <div class=\"nm\">${esc(r.category)}</div>\n            <div class=\"mt\">${esc(mt)}</div>\n            <div class=\"dots\">${dots}</div>\n          </a>`;\n        });\n        document.getElementById(\"rooms-slot\").innerHTML =\n          `<div class=\"rooms-head\">どの部屋に いく？</div><div class=\"rooms\">${cards.join(\"\")}</div>`;\n      }\n\n      // 隠し部屋。額・カテゴリはサーバーが状態に応じて null を返す（??? はクライアント演出ではない）\n      function renderBoss(h) {\n        if (!h) return;\n        const slot = document.getElementById(\"boss-slot\");\n        const cap = \"1人あたり上限 2,000pt\";\n        const amount = (n, capText) => `<div class=\"amt\"><span class=\"n\">${n === null ? \"???\" : Number(n).toLocaleString()}</span><span class=\"u\">pt</span><span class=\"cap\">${esc(capText)}</span></div>`;\n\n        if (h.state === \"locked\") {\n          let hintText = \"とつぜん あらわれます\";\n          if (h.hint.mode === \"rooms_cleared\") {\n            const left = Math.max(1, (h.hint.roomsNeeded || 1) - h.hint.roomsCleared);\n            hintText = `あと ${left}部屋 クリアで ひらく`;\n          } else if (h.hint.mode === \"schedule\" && h.hint.opensAt) {\n            const d = new Date(h.hint.opensAt);\n            hintText = `${d.getMonth() + 1}月${d.getDate()}日 ${d.getHours()}時 にひらく`;\n          } else if (h.hint.mode === \"first_n\") {\n            hintText = `先着 ${h.hint.firstN}名 まで はいれます`;\n          }\n          slot.innerHTML = `<div class=\"boss\"><span class=\"k\">HIDDEN ROOM</span>\n            <h3>まだ ひらいていない 部屋があります。</h3>\n            <p>ここだけ、ふだんより大きく返ってきます。</p>\n            ${amount(null, `ひらくと わかります・${cap}`)}\n            <button class=\"btn\" disabled>${esc(hintText)}</button></div>`;\n          return;\n        }\n        if (h.state === \"full\") {\n          slot.innerHTML = `<div class=\"boss\"><span class=\"k\">HIDDEN ROOM</span>\n            <h3>この部屋は 満員になりました。</h3>\n            <p>つぎの企画を おたのしみに。</p></div>`;\n          return;\n        }\n        if (h.state === \"open\") {\n          const rule = h.awardMode === \"split\"\n            ? [\"参加した人で分けます\", `<p>この部屋のアンケートに こたえた人で 分け合います。<br>結果は しめきり後に LINEで お知らせします。</p>`]\n            : h.awardMode === \"raffle\"\n              ? [`こたえた人から 抽選で ${h.winnersCount}名`, `<p>この部屋のアンケートに こたえると 参加できます。<br>結果は しめきり後に LINEで お知らせします。</p>`]\n              : [\"こたえた人 全員\", `<p>この部屋のアンケートに こたえると もらえます。</p>`];\n          const points = h.awardMode === \"split\" ? h.potPoints\n            : h.awardMode === \"raffle\" ? h.prizePoints : h.flatPoints;\n          const done = h.myAwardPoints !== null;\n          const note = done\n            ? `<p><b>${h.myAwardPoints}pt 受け取りました！</b></p>`\n            : h.qualified\n              ? `<p><b>参加できています。</b>結果を おまちください。</p>`\n              : \"\";\n          const btnLabel = h.hasEntered ? \"部屋の アンケートへ\" : \"この部屋に はいる\";\n          slot.innerHTML = `<div class=\"boss\"><span class=\"k\">HIDDEN ROOM — OPEN</span>\n            <h3>ひらきました。</h3>${rule[1]}\n            ${amount(points, `${rule[0]}・${cap}`)}${note}\n            <button class=\"btn\" id=\"boss-enter\">${esc(btnLabel)}</button></div>`;\n          document.getElementById(\"boss-enter\").addEventListener(\"click\", async (e) => {\n            const btn = e.currentTarget;\n            btn.disabled = true;\n            try {\n              if (!h.hasEntered) {\n                const res = await fetch(`/liff/mission/${encodeURIComponent(initialData.missionId)}/hidden-room/enter`, {\n                  method: \"POST\", headers: { Authorization: `Bearer ${idToken}` },\n                });\n                const data = await res.json().catch(() => ({}));\n                if (!res.ok) throw new Error(data.message || \"はいれませんでした。\");\n              }\n              location.href = projectsUrl(h.category);\n            } catch (err) {\n              alert(err.message || \"はいれませんでした。\");\n              btn.disabled = false;\n            }\n          });\n          return;\n        }\n        if (h.state === \"awaiting\") {\n          slot.innerHTML = `<div class=\"boss\"><span class=\"k\">HIDDEN ROOM</span>\n            <h3>しめきりました。</h3>\n            <p>結果は まもなく LINEで お知らせします。</p></div>`;\n          return;\n        }\n        // settled\n        const settledBody = h.myAwardPoints !== null\n          ? `<h3>${h.myAwardPoints}pt 受け取りました！</h3><p>参加ありがとうございました。</p>`\n          : h.qualified && h.awardMode === \"raffle\"\n            ? `<h3>今回は 当たりませんでした。</h3><p>参加ありがとうございました。つぎの企画を おたのしみに。</p>`\n            : `<h3>この部屋は おわりました。</h3><p>つぎの企画を おたのしみに。</p>`;\n        slot.innerHTML = `<div class=\"boss\"><span class=\"k\">HIDDEN ROOM</span>${settledBody}</div>`;\n      }\n\n      async function load() {\n        try {\n          idToken = await LiffAuth.initLiffOrWebAuth(initialData.liffId);\n          if (!idToken) return;\n          const res = await fetch(`/liff/mission/${encodeURIComponent(initialData.missionId)}/data`, {\n            headers: { Authorization: `Bearer ${idToken}` },\n          });\n          const data = await res.json().catch(() => ({}));\n          if (!res.ok) throw new Error(data.message || \"読み込みに失敗しました。\");\n          $(\"loading\").hidden = true;\n          $(\"answer-count\").textContent = String(data.answers);\n          if (data.remaining) {\n            const r = data.remaining;\n            $(\"togo\").innerHTML = r.answersLeft > 0\n              ? `あと <b>${r.answersLeft}問</b> でつぎの段`\n              : \"\";\n          } else {\n            $(\"togo\").textContent = \"ぜんぶ 上りきりました\";\n          }\n          renderStages(data);\n          renderGauge(data.gauge);\n          renderRooms(data.rooms);\n          renderBoss(data.hiddenRoom);\n        } catch (err) {\n          $(\"loading\").textContent = err.message || \"読み込みに失敗しました。\";\n        }\n      }\n\n      $(\"issue-invite\")?.addEventListener(\"click\", async () => {\n        const btn = $(\"issue-invite\");\n        btn.disabled = true;\n        try {\n          const res = await fetch(\"/liff/invites\", {\n            method: \"POST\",\n            headers: { Authorization: `Bearer ${idToken}` },\n          });\n          const data = await res.json().catch(() => ({}));\n          if (!res.ok) throw new Error(data.message || \"発行できませんでした。\");\n          const box = $(\"invite-url\");\n          box.textContent = data.url;\n          box.style.display = \"block\";\n          if (navigator.share) {\n            await navigator.share({ text: `Hibi に招待します！ ${data.url}` }).catch(() => {});\n          } else if (navigator.clipboard) {\n            await navigator.clipboard.writeText(data.url).catch(() => {});\n            btn.textContent = \"リンクをコピーしました\";\n          }\n        } catch (err) {\n          alert(err.message || \"発行できませんでした。\");\n        } finally {\n          btn.disabled = false;\n        }\n      });\n\n      void load();\n    })();\n    </script>\n  </body>\n</html>\n")
