    ; __append("\n\n    <div id=\"initial-data\" hidden data-json='")
    ; __append(escapeFn( JSON.stringify(initialData) ))
    ; __append("'></div>\n\n    <script>\n    (() => {\n      const initialData = JSON.parse(document.getElementById(\"initial-data\").dataset.json || \"{}\");\n      const { liffId, mode, next, sessionId, profileUrl, updateUrl, confirmMypageUrl, historyUrl, pointsUrl, exchangeRequestUrl, consentStatusUrl, consentPageUrl, documentBaseUrl, interactionsUrl } = initialData;\n      const appView   = document.getElementById(\"app-view\");\n      const loadingView = document.getElementById(\"loading-view\");\n      let idToken = null;\n      // 直近のランク状態（デイリー回答での昇格演出用）。ダッシュボード描画時に更新する。\n      let lastPointStatus = null;\n\n      // ---- ユーティリティ ----\n      function esc(v) {\n        return String(v ?? \"\").replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\").replace(/\"/g,\"&quot;\").replace(/'/g,\"&#39;\");\n      }\n      function sel(v, t) { return v === t ? \"selected\" : \"\"; }\n      function chk(v, t) { return v === t ? \"checked\" : \"\"; }\n      function inArr(arr, v) { return (arr||[]).includes(v) ? \"checked\" : \"\"; }\n\n      // 世帯年収の選択肢（値はサーバー側 parseIncome / lib/rawdataExport.ts INCOME_CODES と対応）\n      const incomeOptions = [\n        [\"under_200\", \"200万円未満\"],\n        [\"200_400\", \"200〜400万円未満\"],\n        [\"400_600\", \"400〜600万円未満\"],\n        [\"600_800\", \"600〜800万円未満\"],\n        [\"800_1000\", \"800〜1,000万円未満\"],\n        [\"1000_1500\", \"1,000〜1,500万円未満\"],\n        [\"1500_2000\", \"1,500〜2,000万円未満\"],\n        [\"over_2000\", \"2,000万円以上\"],\n        [\"unknown\", \"わからない\"],\n        [\"no_answer\", \"答えたくない\"]\n      ];\n\n      function show(html) {\n        loadingView.style.display = \"none\";\n        appView.style.display = \"\";\n        appView.innerHTML = html;\n      }\n\n      function showError(msg) {\n        show(`<div class=\"card\" style=\"text-align:center;padding:40px 20px;\">\n          <div style=\"font-size:40px;margin-bottom:12px;\">⚠️</div>\n          <p style=\"color:#c0392b;font-size:14px;\">${esc(msg)}</p>\n        </div>`);\n      }\n\n      // ---- ランクバッジクラス ----\n      function rankClass(code) {\n        if (!code) return \"\";\n        const c = code.toLowerCase();\n        if (c.includes(\"silver\"))   return \"silver\";\n        if (c.includes(\"gold\"))     return \"gold\";\n        if (c.includes(\"platinum\")) return \"platinum\";\n        return \"\";\n      }\n\n      // ---- ポイントバーの幅 ----\n      function progressWidth(current, next) {\n        if (!next || next <= 0) return 100;\n        const pct = Math.min(100, Math.round((current / next) * 100));\n        return pct;\n      }\n\n      // ---- 日付フォーマット ----\n      function fmtDate(iso) {\n        if (!iso) return \"\";\n        try {\n          const d = new Date(iso);\n          return `${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,\"0\")}/${String(d.getDate()).padStart(2,\"0\")}`;\n        } catch { return \"\"; }\n      }\n\n      // ---- ダッシュボード描画 ----\n      function renderDashboard(data) {\n        const p      = data.profile || {};\n        const s      = data.stats   || {};\n        const txs    = data.recent_transactions || [];\n        const badges = data.awarded_badges || [];\n        const name   = p.nickname || data.display_name || \"ゲスト\";\n        const initial = name.charAt(0).toUpperCase();\n        const pct    = progressWidth(s.total_points, s.next_rank_min_points);\n        const streak = s.current_streak ?? 0;\n        // 昇格判定の基準（回答前ランク）。デイリー回答の onAnswered で next と比較する。\n        lastPointStatus = { rank_code: s.rank_code, rank_name: s.rank_name || \"ブロンズ\", tier: s.tier };\n\n        const txHtml = txs.length === 0\n          ? `<li class=\"tx-item\"><span class=\"tx-reason\" style=\"color:#999\">まだ履歴がありません</span></li>`\n          : txs.map(tx => `\n            <li class=\"tx-item\">\n              <span class=\"tx-reason\">${esc(tx.reason)}</span>\n              <span class=\"tx-date\">${fmtDate(tx.created_at)}</span>\n              <span class=\"tx-points\">+${tx.points}pt</span>\n            </li>`).join(\"\");\n\n        const nextRankInfo = s.next_rank_name\n          ? `次のランク: ${esc(s.next_rank_name)}（あと ${s.next_rank_min_points - s.total_points}pt）`\n          : `最高ランク達成！`;\n\n        // 誠実度（5段階）。素材が足りないうちはサーバーが null を返すので、その間は出さない。\n        // 生の係数や判定理由は出さない＝式が見えると対策され、回答の真値性が落ちるため。\n        const h = s.honesty;\n        const honestyHtml = !h ? \"\" : `\n          <div class=\"card honesty-card\">\n            <div class=\"honesty-head\">\n              <span class=\"honesty-title\">回答の安定度</span>\n              <span class=\"honesty-stars\">${\"★\".repeat(Math.max(0, Math.min(5, h.stars)))}<span class=\"off\">${\"★\".repeat(5 - Math.max(0, Math.min(5, h.stars)))}</span></span>\n            </div>\n            <div class=\"honesty-note\">${esc(h.label)}／ていねいな回答ほどポイントが貯まりやすくなります。</div>\n          </div>`;\n\n        const badgeHtml = badges.length === 0\n          ? `<p style=\"font-size:12px;color:#999;text-align:center;padding:8px 0\">まだバッジがありません</p>`\n          : badges.slice(0, 6).map(b => `\n              <div style=\"text-align:center;font-size:11px;color:#60726f;flex:1;min-width:60px;max-width:80px;\">\n                <div style=\"font-size:28px;margin-bottom:2px;\">${esc(b.badge_icon || \"🏅\")}</div>\n                <div style=\"word-break:break-all;line-height:1.3\">${esc(b.badge_name || b.badge_code)}</div>\n              </div>`).join(\"\");\n\n        show(`\n          <div class=\"card\">\n            <div class=\"profile-header\">\n              <div class=\"avatar\">${esc(initial)}</div>\n              <div>\n                <div class=\"profile-name\">${esc(name)}</div>\n                <div class=\"rank-line\">\n                  ${(window.RankIcons && s.rank_code) ? RankIcons.badge(s.rank_code, s.tier || 1, 46) : \"\"}\n                  <span class=\"rank-name\">${esc(s.rank_name || \"ブロンズ\")}${s.tier ? \" \" + [\"I\", \"II\", \"III\"][s.tier - 1] : \"\"}</span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"stats-row\">\n            <div class=\"stat-box\">\n              <div class=\"stat-value\">${s.total_points ?? 0}<span class=\"stat-unit\">pt</span></div>\n              <div class=\"stat-label\">現在のポイント</div>\n            </div>\n            <div class=\"stat-box\">\n              <div class=\"stat-value\">${s.completed_count ?? 0}<span class=\"stat-unit\" style=\"font-size:14px\">件</span></div>\n              <div class=\"stat-label\">回答済み案件</div>\n            </div>\n            <div class=\"stat-box\">\n              <div class=\"stat-value\">${streak}<span class=\"stat-unit\" style=\"font-size:14px\">日</span></div>\n              <div class=\"stat-label\">連続回答</div>\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <div class=\"progress-section\">\n              <div class=\"progress-label\">\n                <span>ランク進捗</span>\n                <span>${nextRankInfo}</span>\n              </div>\n              <div class=\"progress-bar-wrap\">\n                <div class=\"progress-bar\" style=\"width:${pct}%\"></div>\n              </div>\n            </div>\n          </div>\n\n          ${honestyHtml}\n\n          <div class=\"monthly-card\" id=\"monthly-stats-card\" style=\"display:none\">\n            <div class=\"monthly-title\">今月の応募状況</div>\n            <div class=\"monthly-grid\" id=\"monthly-grid\"></div>\n            <div style=\"text-align:right;margin-top:10px\">\n              <a href=\"${interactionsUrl || '/liff/interactions'}\" style=\"font-size:12px;color:#2ca87a;font-weight:600;text-decoration:none\">やりとりを見る →</a>\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <div class=\"section-title\" style=\"margin-bottom:10px\">獲得バッジ</div>\n            <div style=\"display:flex;flex-wrap:wrap;gap:12px;justify-content:flex-start\">\n              ${badgeHtml}\n            </div>\n            ${badges.length > 6 ? `<p style=\"font-size:12px;color:#2ca87a;text-align:center;margin-top:10px\">他 ${badges.length - 6} 個</p>` : \"\"}\n          </div>\n\n          <div class=\"card\">\n            <div class=\"section-title\">最近のポイント履歴</div>\n            <ul class=\"tx-list\">${txHtml}</ul>\n          </div>\n\n          <div style=\"display:flex;flex-direction:column;gap:10px;margin-bottom:20px;\">\n            <button class=\"btn btn-secondary btn-sm\" id=\"btn-history\">回答履歴を見る</button>\n            <button class=\"btn btn-secondary btn-sm\" id=\"btn-points-detail\">ポイント明細を見る</button>\n            <button class=\"btn btn-secondary btn-sm\" id=\"btn-edit-profile\">プロフィールを編集</button>\n            <button class=\"btn btn-secondary btn-sm\" id=\"btn-consent\">規約・同意状況</button>\n          </div>\n        `);\n\n        // 今月の応募状況を非同期ロード\n        loadMonthlyStats();\n\n        document.getElementById(\"btn-history\")?.addEventListener(\"click\", () => {\n          renderHistory();\n        });\n        document.getElementById(\"btn-points-detail\")?.addEventListener(\"click\", () => {\n          renderPointsDetail();\n        });\n        document.getElementById(\"btn-edit-profile\")?.addEventListener(\"click\", () => {\n          renderEditForm(data.profile);\n        });\n        document.getElementById(\"btn-consent\")?.addEventListener(\"click\", () => {\n          renderConsentPage();\n        });\n      }\n\n      // ---- 初回セットアップ描画 ----\n      function renderSetupForm(profile) {\n        const p = profile || {};\n        const prefectures = [\"北海道\",\"青森県\",\"岩手県\",\"宮城県\",\"秋田県\",\"山形県\",\"福島県\",\"茨城県\",\"栃木県\",\"群馬県\",\"埼玉県\",\"千葉県\",\"東京都\",\"神奈川県\",\"新潟県\",\"富山県\",\"石川県\",\"福井県\",\"山梨県\",\"長野県\",\"岐阜県\",\"静岡県\",\"愛知県\",\"三重県\",\"滋賀県\",\"京都府\",\"大阪府\",\"兵庫県\",\"奈良県\",\"和歌山県\",\"鳥取県\",\"島根県\",\"岡山県\",\"広島県\",\"山口県\",\"徳島県\",\"香川県\",\"愛媛県\",\"高知県\",\"福岡県\",\"佐賀県\",\"長崎県\",\"熊本県\",\"大分県\",\"宮崎県\",\"鹿児島県\",\"沖縄県\"];\n        show(`\n          <div class=\"card\">\n            <div class=\"setup-header\">\n              <div class=\"icon\">📝</div>\n              <h2>プロフィール設定</h2>\n              <p>案件に参加する前に、基本情報を登録してください。<br>所要時間：約2分</p>\n            </div>\n          </div>\n          <div class=\"card\">\n            <div class=\"section-title\" style=\"margin-bottom:4px\">必須項目</div>\n            <p style=\"font-size:12px;color:#60726f;margin-bottom:14px\">以下の項目は全て入力が必要です。</p>\n            <form id=\"setup-form\" class=\"form-stack\">\n              <div class=\"form-group\">\n                <label>呼び名<span class=\"required\">必須</span></label>\n                <input class=\"form-control\" type=\"text\" name=\"nickname\" value=\"${esc(p.nickname)}\" placeholder=\"例：たろう\" required />\n              </div>\n              <div class=\"form-group\">\n                <label>生年月日<span class=\"required\">必須</span></label>\n                <input class=\"form-control\" type=\"date\" name=\"birth_date\" value=\"${esc(p.birth_date) || '2000-01-01'}\" max=\"${new Date().toISOString().slice(0,10)}\" required />\n              </div>\n              <div class=\"form-group\">\n                <label>性別<span class=\"required\">必須</span></label>\n                <div class=\"radio-group\">\n                  ${[[\"male\",\"男性\"],[\"female\",\"女性\"],[\"other\",\"その他\"],[\"prefer_not_to_say\",\"答えたくない\"]].map(([v,l]) =>\n                    `<label><input type=\"radio\" name=\"gender\" value=\"${v}\" ${chk(p.gender, v)} required />${l}</label>`\n                  ).join(\"\")}\n                </div>\n              </div>\n              <div class=\"form-group\">\n                <label>都道府県<span class=\"required\">必須</span></label>\n                <select class=\"form-control\" name=\"prefecture\" required>\n                  <option value=\"\">選択してください</option>\n                  ${prefectures.map(pref => `<option value=\"${esc(pref)}\" ${sel(p.prefecture, pref)}>${esc(pref)}</option>`).join(\"\")}\n                </select>\n              </div>\n              <div class=\"form-group\">\n                <label>職業<span class=\"required\">必須</span></label>\n                <select class=\"form-control\" name=\"occupation\" required>\n                  <option value=\"\">選択してください</option>\n                  ${[\"会社員（正社員）\",\"会社員（契約・派遣）\",\"公務員\",\"自営業・フリーランス\",\"パート・アルバイト\",\"学生\",\"専業主婦・主夫\",\"無職\",\"その他\"].map(o => `<option value=\"${esc(o)}\" ${sel(p.occupation, o)}>${esc(o)}</option>`).join(\"\")}\n                </select>\n              </div>\n              <div class=\"form-group\">\n                <label>業種<span class=\"required\">必須</span></label>\n                <select class=\"form-control\" name=\"industry\" required>\n                  <option value=\"\">選択してください</option>\n                  ${[\"IT・通信\",\"製造\",\"金融・保険\",\"医療・福祉\",\"教育\",\"小売・流通\",\"外食・フード\",\"建設・不動産\",\"メディア・広告\",\"公共・行政\",\"その他\"].map(i => `<option value=\"${esc(i)}\" ${sel(p.industry, i)}>${esc(i)}</option>`).join(\"\")}\n                </select>\n              </div>\n\n              <div class=\"card\" style=\"background:#f8faf9;border-radius:12px;padding:14px;margin-top:4px\">\n                <div class=\"section-title\" style=\"margin-bottom:8px\">推奨項目（任意）</div>\n                <p style=\"font-size:12px;color:#60726f;margin-bottom:12px;line-height:1.6\">\n                  アンケートには「お子さまがいる方」「特定のご職業の方」など、プロフィールが条件になっているものがあります。\n                  任意項目も埋めておくほど<strong style=\"color:#2e7d5b\">答えられるアンケートが増え、ポイントを貯めるチャンスが広がります</strong>。\n                  未入力の項目が条件のアンケートは届かないことがあります。\n                </p>\n                <div class=\"form-stack\">\n                  <div class=\"form-group\">\n                    <label>婚姻状況</label>\n                    <div class=\"radio-group\">\n                      ${[[\"single\",\"未婚\"],[\"married\",\"既婚\"],[\"divorced\",\"離婚\"],[\"widowed\",\"死別\"]].map(([v,l]) =>\n                        `<label><input type=\"radio\" name=\"marital_status\" value=\"${v}\" ${chk(p.marital_status, v)} />${l}</label>`\n                      ).join(\"\")}\n                    </div>\n                  </div>\n                  <div class=\"form-group\">\n                    <label>子どもの有無</label>\n                    <div class=\"radio-group\">\n                      <label><input type=\"radio\" name=\"has_children\" value=\"true\"  ${p.has_children === true  ? \"checked\" : \"\"} />いる</label>\n                      <label><input type=\"radio\" name=\"has_children\" value=\"false\" ${p.has_children === false ? \"checked\" : \"\"} />いない</label>\n                    </div>\n                  </div>\n                  <div class=\"form-group\">\n                    <label>世帯年収</label>\n                    <select class=\"form-control\" name=\"household_income\">\n                      <option value=\"\">選択してください</option>\n                      ${incomeOptions.map(([v,l]) => `<option value=\"${v}\" ${sel(p.household_income, v)}>${l}</option>`).join(\"\")}\n                    </select>\n                  </div>\n                </div>\n              </div>\n\n              <p style=\"font-size:12px;color:#60726f;line-height:1.6;margin-top:4px\">\n                利用規約・プライバシーポリシーへの同意は確認済みです。内容は「マイページ」からいつでも再確認できます。\n              </p>\n              <p id=\"setup-status\" class=\"status-msg\"></p>\n              <button type=\"submit\" class=\"btn btn-primary\">登録して始める</button>\n            </form>\n          </div>\n        `);\n\n        document.getElementById(\"setup-form\")?.addEventListener(\"submit\", async (e) => {\n          e.preventDefault();\n          const form = e.target;\n          const fd = new FormData(form);\n          const statusEl = document.getElementById(\"setup-status\");\n\n          // 性別は radio なので HTML required が効かないブラウザ向けに JS バリデーション\n          if (!fd.get(\"gender\")) {\n            statusEl.textContent = \"性別を選択してください。\";\n            statusEl.className = \"status-msg error\";\n            return;\n          }\n\n          statusEl.textContent = \"保存中...\";\n          statusEl.className = \"status-msg\";\n\n          const payload = {\n            nickname:       fd.get(\"nickname\") || null,\n            birth_date:     fd.get(\"birth_date\") || null,\n            gender:         fd.get(\"gender\") || null,\n            prefecture:     fd.get(\"prefecture\") || null,\n            occupation:     fd.get(\"occupation\") || null,\n            industry:       fd.get(\"industry\") || null,\n            marital_status: fd.get(\"marital_status\") || null,\n            has_children:   fd.get(\"has_children\") === \"true\" ? true : fd.get(\"has_children\") === \"false\" ? false : null,\n            household_income: fd.get(\"household_income\") || null,\n          };\n\n          try {\n            const res = await fetch(updateUrl, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\", Authorization: `Bearer ${idToken}` },\n              body: JSON.stringify(payload)\n            });\n            if (!res.ok) throw new Error(\"保存に失敗しました。\");\n            const json = await res.json();\n\n            // マイページ確認完了をセッションに記録してからnextへ遷移\n            async function confirmAndNavigate(destination) {\n              if (confirmMypageUrl && sessionId) {\n                try {\n                  await fetch(confirmMypageUrl, {\n                    method: \"POST\",\n                    headers: { \"Content-Type\": \"application/json\" },\n                    body: JSON.stringify({ session_id: sessionId })\n                  });\n                } catch(e) {\n                  console.warn(\"confirm-mypage failed\", e);\n                }\n              }\n              window.location.href = destination;\n            }\n\n            if (json.profile_just_completed) {\n              statusEl.textContent = \"登録完了！\";\n              statusEl.className = \"status-msg success\";\n              if (next) {\n                setTimeout(() => confirmAndNavigate(next), 800);\n              } else {\n                setTimeout(() => load(), 800);\n              }\n            } else {\n              statusEl.textContent = \"保存しました。\";\n              statusEl.className = \"status-msg success\";\n              if (next) {\n                setTimeout(() => confirmAndNavigate(next), 800);\n              }\n            }\n          } catch (err) {\n            statusEl.textContent = err.message || \"保存に失敗しました。\";\n            statusEl.className = \"status-msg error\";\n          }\n        });\n      }\n\n      // ---- 回答履歴描画 ----\n      async function renderHistory() {\n        show(`<div id=\"loading-inner\" style=\"text-align:center;padding:40px;color:#60726f\">読み込み中...</div>`);\n        try {\n          const res = await fetch(historyUrl, { headers: { Authorization: `Bearer ${idToken}` } });\n          if (!res.ok) throw new Error(\"取得に失敗しました\");\n          const data = await res.json();\n          const history = data.history || [];\n\n          const statusLabel = {\n            assigned: \"未開始\", sent: \"送付済\", opened: \"開封済\",\n            started: \"回答中\", completed: \"完了\", expired: \"期限切れ\", cancelled: \"キャンセル\"\n          };\n          const statusColor = { completed: \"#2ca87a\", expired: \"#999\", cancelled: \"#999\" };\n\n          const rows = history.length === 0\n            ? `<div style=\"text-align:center;color:#999;padding:24px\">回答履歴がありません</div>`\n            : history.map(h => `\n              <div class=\"tx-item\" style=\"flex-direction:column;align-items:flex-start;gap:4px;padding:12px 0\">\n                <div style=\"display:flex;justify-content:space-between;width:100%\">\n                  <span style=\"font-weight:600;font-size:14px\">${esc(h.project_name)}</span>\n                  <span style=\"font-size:12px;font-weight:600;color:${statusColor[h.status]||'#333'}\">${statusLabel[h.status]||h.status}</span>\n                </div>\n                <div style=\"display:flex;justify-content:space-between;width:100%\">\n                  <span style=\"font-size:12px;color:#60726f\">${fmtDate(h.assigned_at)}</span>\n                  ${h.status === 'completed' && h.reward_points ? `<span style=\"font-size:12px;color:#2ca87a;font-weight:600\">+${h.reward_points}pt</span>` : ''}\n                </div>\n              </div>`).join(\"\");\n\n          show(`\n            <div class=\"card\" style=\"display:flex;align-items:center;gap:12px;padding:14px 20px;\">\n              <button id=\"btn-back\" style=\"background:none;border:none;font-size:20px;cursor:pointer;padding:0;\">←</button>\n              <span style=\"font-weight:600;font-size:16px;\">回答履歴</span>\n            </div>\n            <div class=\"card\">\n              <div class=\"section-title\" style=\"margin-bottom:8px\">全${history.length}件</div>\n              <ul class=\"tx-list\">${rows}</ul>\n            </div>\n          `);\n          document.getElementById(\"btn-back\")?.addEventListener(\"click\", () => load());\n        } catch (err) {\n          showError(err.message || \"読み込みに失敗しました\");\n        }\n      }\n\n      // ---- ポイント画面 ----\n      async function renderPointsDetail() {\n        show(`<div style=\"text-align:center;padding:40px;color:#60726f\">読み込み中...</div>`);\n        try {\n          const res = await fetch(pointsUrl, { headers: { Authorization: `Bearer ${idToken}` } });\n          if (!res.ok) throw new Error(\"取得に失敗しました\");\n          const data = await res.json();\n          renderPointsView(data);\n        } catch (err) {\n          showError(err.message || \"読み込みに失敗しました\");\n        }\n      }\n\n      function renderPointsView(data, activeTab = \"exchange\") {\n        const bal      = data.balance  || {};\n        const histories = data.histories || [];\n        const exchanges = data.exchanges || [];\n\n        const available = bal.available_points ?? 0;\n        const pending   = bal.pending_points   ?? 0;\n        const lifetime  = bal.lifetime_points  ?? 0;\n\n        // 交換進捗\n        const UNIT = 500;\n        const remainder    = available % UNIT;\n        const shortfall    = remainder === 0 && available > 0 ? 0 : UNIT - remainder;\n        const progressPct  = Math.min(100, Math.round((remainder === 0 && available >= UNIT ? UNIT : remainder) / UNIT * 100));\n        const canExchange  = available >= UNIT;\n        const hasPending   = exchanges.some(e => e.status === \"pending\");\n        const exchangeCount = Math.floor(available / UNIT);\n\n        // バランスカード\n        const progressHtml = `\n          <div class=\"exchange-progress-wrap\">\n            <div class=\"exchange-progress-bar\" style=\"width:${canExchange ? 100 : progressPct}%\"></div>\n          </div>\n          <div class=\"exchange-progress-label\">\n            ${canExchange\n              ? `${exchangeCount}口（${available}pt）交換可能`\n              : `次の交換まであと ${shortfall}pt`}\n          </div>`;\n\n        const exchangeBtnHtml = hasPending\n          ? `<div class=\"btn-exchange-pending\">申請中（承認をお待ちください）</div>`\n          : canExchange\n            ? `<button id=\"btn-do-exchange\" class=\"btn-exchange\">ポイントを交換申請する</button>`\n            : `<button class=\"btn-exchange\" disabled>500pt に達したら交換できます</button>`;\n\n        // 交換履歴\n        const exchangeStatusLabel = {\n          pending: \"申請中\", approved: \"承認済\", fulfilled: \"送付済\", rejected: \"却下\", canceled: \"キャンセル\"\n        };\n        const exchangeStatusClass = {\n          pending: \"badge-pending\", approved: \"badge-approved\", fulfilled: \"badge-fulfilled\",\n          rejected: \"badge-rejected\", canceled: \"badge-canceled\"\n        };\n\n        const exchangeRows = exchanges.length === 0\n          ? `<div style=\"text-align:center;color:#999;padding:16px;font-size:13px\">交換申請はまだありません</div>`\n          : exchanges.map(e => {\n            const giftHtml = e.status === \"fulfilled\" && e.gift_url\n              ? `<div class=\"gift-url-box\">\n                   <div class=\"gift-url-label\">ギフトURL（有効期限内にご使用ください）</div>\n                   <a href=\"${esc(e.gift_url)}\" target=\"_blank\">${esc(e.gift_url)}</a>\n                 </div>`\n              : \"\";\n            const cancelBtn = e.status === \"pending\"\n              ? `<button class=\"btn-cancel-exchange btn btn-secondary btn-sm\" data-id=\"${esc(e.id)}\"\n                   style=\"margin-top:8px;font-size:12px;padding:7px 12px;width:auto\">申請をキャンセル</button>`\n              : \"\";\n            const failedNote = e.status === \"rejected\" && e.failed_reason\n              ? `<div style=\"font-size:12px;color:#c0392b;margin-top:4px\">却下理由: ${esc(e.failed_reason)}</div>`\n              : \"\";\n            return `\n              <div style=\"padding:14px 0;border-bottom:1px solid #f0f4f3\">\n                <div style=\"display:flex;justify-content:space-between;align-items:center\">\n                  <span style=\"font-size:15px;font-weight:700;color:#1a2f2a\">${e.requested_points}pt</span>\n                  <span class=\"exchange-status-badge ${exchangeStatusClass[e.status] || ''}\">${exchangeStatusLabel[e.status] || e.status}</span>\n                </div>\n                <div style=\"font-size:12px;color:#60726f;margin-top:3px\">${fmtDate(e.requested_at)} 申請</div>\n                ${failedNote}\n                ${giftHtml}\n                ${cancelBtn}\n              </div>`;\n          }).join(\"\");\n\n        // ポイント履歴\n        const typeLabel = {\n          project_completion: \"案件完了\", first_bonus: \"初回ボーナス\",\n          continuity_bonus: \"継続ボーナス\", project_bonus: \"案件ボーナス\",\n          daily_survey: \"デイリー回答\", interview_complete: \"インタビュー完了\",\n          streak_bonus: \"ストリークボーナス\", birthday_bonus: \"誕生日ボーナス\",\n          campaign_bonus: \"キャンペーン\", attribute_update: \"プロフィール更新\",\n          manual_adjustment: \"手動調整\", redemption: \"交換\",\n          exchange_request: \"交換申請（仮押さえ）\", exchange_cancel: \"申請キャンセル（返還）\",\n          exchange_refund: \"申請却下（返還）\"\n        };\n\n        const historyRows = histories.length === 0\n          ? `<li class=\"tx-item\"><span class=\"tx-reason\" style=\"color:#999\">ポイント履歴がありません</span></li>`\n          : histories.map(t => `\n            <li class=\"tx-item\">\n              <span class=\"tx-reason\">${esc(t.reason || typeLabel[t.type] || t.type)}</span>\n              <span class=\"tx-date\">${fmtDate(t.created_at)}</span>\n              <span class=\"tx-points\" style=\"color:${t.points >= 0 ? '#2ca87a' : '#c0392b'}\">\n                ${t.points >= 0 ? '+' : ''}${t.points}pt\n              </span>\n            </li>`).join(\"\");\n\n        show(`\n          <div class=\"card\" style=\"display:flex;align-items:center;gap:12px;padding:14px 20px;\">\n            <button id=\"btn-back\" style=\"background:none;border:none;font-size:20px;cursor:pointer;padding:0;\">←</button>\n            <span style=\"font-weight:600;font-size:16px;\">ポイント</span>\n          </div>\n\n          <div class=\"balance-card\">\n            <div class=\"balance-label\">保有ポイント</div>\n            <div>\n              <span class=\"balance-main\">${available}</span>\n              <span class=\"balance-unit\">pt</span>\n            </div>\n            <div class=\"balance-sub-row\">\n              <div class=\"balance-sub-item\">\n                <div class=\"balance-sub-val\">${pending}<span style=\"font-size:12px;margin-left:2px\">pt</span></div>\n                <div class=\"balance-sub-lbl\">申請中</div>\n              </div>\n              <div class=\"balance-sub-item\">\n                <div class=\"balance-sub-val\">${lifetime - available - pending}<span style=\"font-size:12px;margin-left:2px\">pt</span></div>\n                <div class=\"balance-sub-lbl\">累計交換</div>\n              </div>\n              <div class=\"balance-sub-item\">\n                <div class=\"balance-sub-val\">${lifetime}<span style=\"font-size:12px;margin-left:2px\">pt</span></div>\n                <div class=\"balance-sub-lbl\">累計獲得</div>\n              </div>\n            </div>\n            ${progressHtml}\n            <div style=\"margin-top:14px\">${exchangeBtnHtml}</div>\n          </div>\n\n          <div class=\"card\">\n            <div class=\"tab-bar\">\n              <button class=\"tab-btn ${activeTab === 'exchange' ? 'active' : ''}\" id=\"tab-exchange\">交換申請履歴</button>\n              <button class=\"tab-btn ${activeTab === 'history'  ? 'active' : ''}\" id=\"tab-history\">ポイント履歴</button>\n            </div>\n            <div id=\"pane-exchange\" style=\"display:${activeTab === 'exchange' ? '' : 'none'}\">\n              ${exchangeRows}\n            </div>\n            <div id=\"pane-history\" style=\"display:${activeTab === 'history' ? '' : 'none'}\">\n              <ul class=\"tx-list\">${historyRows}</ul>\n            </div>\n          </div>\n        `);\n\n        // ---- イベント ----\n        document.getElementById(\"btn-back\")?.addEventListener(\"click\", () => load());\n\n        // タブ切替\n        document.getElementById(\"tab-exchange\")?.addEventListener(\"click\", () => {\n          document.getElementById(\"pane-exchange\").style.display = \"\";\n          document.getElementById(\"pane-history\").style.display  = \"none\";\n          document.getElementById(\"tab-exchange\").classList.add(\"active\");\n          document.getElementById(\"tab-history\").classList.remove(\"active\");\n        });\n        document.getElementById(\"tab-history\")?.addEventListener(\"click\", () => {\n          document.getElementById(\"pane-history\").style.display  = \"\";\n          document.getElementById(\"pane-exchange\").style.display = \"none\";\n          document.getElementById(\"tab-history\").classList.add(\"active\");\n          document.getElementById(\"tab-exchange\").classList.remove(\"active\");\n        });\n\n        // 交換申請\n        document.getElementById(\"btn-do-exchange\")?.addEventListener(\"click\", () => {\n          showExchangeConfirm(available, data);\n        });\n\n        // 申請キャンセル\n        document.querySelectorAll(\".btn-cancel-exchange\").forEach(btn => {\n          btn.addEventListener(\"click\", async () => {\n            const requestId = btn.dataset.id;\n            if (!requestId) return;\n            if (!confirm(\"交換申請をキャンセルしますか？ポイントは返還されます。\")) return;\n            btn.disabled = true;\n            try {\n              const r = await fetch(`${exchangeRequestUrl}/${requestId}/cancel`, {\n                method: \"POST\",\n                headers: { Authorization: `Bearer ${idToken}` }\n              });\n              const j = await r.json();\n              if (!r.ok) throw new Error(j.error || \"キャンセルに失敗しました\");\n              await reloadPointsView();\n            } catch (e) {\n              alert(e.message || \"エラーが発生しました\");\n              btn.disabled = false;\n            }\n          });\n        });\n      }\n\n      function showExchangeConfirm(available, cachedData) {\n        const UNIT = 500;\n        const count = Math.floor(available / UNIT);\n        // 500pt刻みで保有上限まで選択できる（500pt = 500円分）\n        const optionsHtml = Array.from({ length: count }, (_, i) => {\n          const p = (i + 1) * UNIT;\n          return `<option value=\"${p}\">${p.toLocaleString()}pt（${p.toLocaleString()}円分）</option>`;\n        }).join(\"\");\n        const overlay = document.createElement(\"div\");\n        overlay.className = \"confirm-overlay\";\n        overlay.innerHTML = `\n          <div class=\"confirm-sheet\">\n            <div class=\"confirm-title\">ポイントを交換申請する</div>\n            <div class=\"confirm-body\">\n              交換するポイントを選択してください（500pt＝500円分）。<br>\n              <select id=\"exchange-points\" style=\"width:100%;margin:10px 0;padding:10px;font-size:15px;border:1px solid #d5e0de;border-radius:8px;background:#fff\">\n                ${optionsHtml}\n              </select>\n              選択したポイントを <strong>Amazonギフト等</strong> と交換申請します。<br>\n              申請後、管理者が確認・承認後にギフトURLをLINEでお送りします。<br><br>\n              <strong>申請後はキャンセル可能</strong>ですが、承認後はキャンセルできません。\n            </div>\n            <p id=\"confirm-status\" class=\"status-msg\"></p>\n            <div class=\"confirm-btns\">\n              <button id=\"confirm-cancel\" class=\"btn btn-secondary\" style=\"flex:1\">閉じる</button>\n              <button id=\"confirm-ok\"     class=\"btn btn-primary\"   style=\"flex:2\">申請する（${UNIT}pt）</button>\n            </div>\n          </div>`;\n        document.body.appendChild(overlay);\n\n        const selectEl = overlay.querySelector(\"#exchange-points\");\n        const okBtnEl  = overlay.querySelector(\"#confirm-ok\");\n        selectEl.addEventListener(\"change\", () => {\n          okBtnEl.textContent = `申請する（${Number(selectEl.value).toLocaleString()}pt）`;\n        });\n\n        overlay.querySelector(\"#confirm-cancel\").addEventListener(\"click\", () => overlay.remove());\n        overlay.addEventListener(\"click\", e => { if (e.target === overlay) overlay.remove(); });\n\n        overlay.querySelector(\"#confirm-ok\").addEventListener(\"click\", async () => {\n          const okBtn  = overlay.querySelector(\"#confirm-ok\");\n          const stEl   = overlay.querySelector(\"#confirm-status\");\n          const pts    = Number(selectEl.value) || UNIT;\n          okBtn.disabled = true;\n          stEl.textContent = \"申請中...\";\n          stEl.className = \"status-msg\";\n          try {\n            const r = await fetch(exchangeRequestUrl, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\", Authorization: `Bearer ${idToken}` },\n              body: JSON.stringify({ requested_points: pts })\n            });\n            const j = await r.json();\n            if (!r.ok) throw new Error(j.error || \"申請に失敗しました\");\n            overlay.remove();\n            await reloadPointsView();\n          } catch (e) {\n            stEl.textContent = e.message || \"エラーが発生しました\";\n            stEl.className = \"status-msg error\";\n            okBtn.disabled = false;\n          }\n        });\n      }\n\n      async function reloadPointsView() {\n        try {\n          const res = await fetch(pointsUrl, { headers: { Authorization: `Bearer ${idToken}` } });\n          if (!res.ok) throw new Error(\"再取得に失敗しました\");\n          renderPointsView(await res.json());\n        } catch (err) {\n          showError(err.message || \"読み込みに失敗しました\");\n        }\n      }\n\n      // ---- 規約・同意状況 ----\n      // バージョン管理された書類（利用規約・PP等）の実際の同意状況を表示し、本文を再確認できる。\n      async function renderConsentPage() {\n        show(`<div style=\"text-align:center;padding:40px;color:#60726f\">読み込み中...</div>`);\n        try {\n          const res = await fetch(consentStatusUrl, { headers: { Authorization: `Bearer ${idToken}` } });\n          if (!res.ok) throw new Error(\"取得に失敗しました\");\n          const data = await res.json();\n          const statuses = data.statuses || [];\n\n          const rows = statuses.length === 0\n            ? `<p style=\"font-size:13px;color:#60726f;padding:8px 0\">現在、同意が必要な書類はありません。</p>`\n            : statuses.map(s => {\n              let badge;\n              if (!s.consented) {\n                badge = `<span style=\"font-size:12px;font-weight:600;color:#c0392b;background:#fdecea;padding:3px 10px;border-radius:12px\">未同意</span>`;\n              } else if (!s.isLatestVersion) {\n                badge = `<span style=\"font-size:12px;font-weight:600;color:#b45309;background:#fbf0e0;padding:3px 10px;border-radius:12px\">要再同意</span>`;\n              } else {\n                badge = `<span style=\"font-size:12px;font-weight:600;color:#1a7a5a;background:#e8f5ef;padding:3px 10px;border-radius:12px\">同意済み</span>`;\n              }\n              const detail = s.consented\n                ? `v${esc(s.consentedVersionNo || \"\")}${s.consentedAt ? \"・\" + fmtDate(s.consentedAt) : \"\"}${!s.isLatestVersion && s.currentVersionNo ? `（最新 v${esc(s.currentVersionNo)}）` : \"\"}`\n                : (s.currentVersionNo ? `最新 v${esc(s.currentVersionNo)}` : \"\");\n              return `\n                <div style=\"display:flex;justify-content:space-between;align-items:center;gap:10px;padding:14px 0;border-bottom:1px solid #f0f4f3\">\n                  <div style=\"flex:1\">\n                    <div style=\"font-size:14px;font-weight:600;color:#1a2f2a\">${esc(s.title)}</div>\n                    <div style=\"font-size:12px;color:#60726f;margin-top:3px\">${detail}</div>\n                  </div>\n                  ${badge}\n                  <button class=\"doc-read-btn\" data-id=\"${esc(s.documentId)}\" data-title=\"${esc(s.title)}\"\n                    style=\"background:none;border:1px solid #cfe0db;border-radius:8px;padding:6px 12px;font-size:12px;color:#2ca87a;cursor:pointer;white-space:nowrap\">読む</button>\n                </div>`;\n            }).join(\"\");\n\n          const reconsentBtn = data.has_unsigned\n            ? `<button id=\"btn-reconsent\" class=\"btn btn-primary\" style=\"margin-top:16px\">未同意・改定された書類を確認する</button>`\n            : \"\";\n\n          show(`\n            <div class=\"card\" style=\"display:flex;align-items:center;gap:12px;padding:14px 20px;\">\n              <button id=\"btn-back\" style=\"background:none;border:none;font-size:20px;cursor:pointer;padding:0;\">←</button>\n              <span style=\"font-weight:600;font-size:16px;\">規約・同意状況</span>\n            </div>\n            <div class=\"card\">\n              <div style=\"font-size:12px;color:#60726f;margin-bottom:8px;line-height:1.6\">\n                ご利用にあたって同意いただいた書類の状況です。本文は「読む」からいつでも再確認できます。\n              </div>\n              ${rows}\n              ${reconsentBtn}\n            </div>\n          `);\n\n          document.getElementById(\"btn-back\")?.addEventListener(\"click\", () => load());\n\n          document.getElementById(\"btn-reconsent\")?.addEventListener(\"click\", () => {\n            const redirect = encodeURIComponent(location.pathname + location.search);\n            location.href = `${consentPageUrl}?mode=update&redirect=${redirect}`;\n          });\n\n          document.querySelectorAll(\".doc-read-btn\").forEach(btn => {\n            btn.addEventListener(\"click\", () => openDocumentOverlay(btn.dataset.id, btn.dataset.title));\n          });\n        } catch (err) {\n          showError(err.message || \"読み込みに失敗しました\");\n        }\n      }\n\n      // ---- 書類本文オーバーレイ（再確認用） ----\n      async function openDocumentOverlay(docId, title) {\n        const overlay = document.createElement(\"div\");\n        overlay.style.cssText = \"position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:1000;display:flex;align-items:flex-end;justify-content:center\";\n        overlay.innerHTML = `\n          <div style=\"background:#fff;width:100%;max-width:560px;max-height:85vh;border-radius:16px 16px 0 0;display:flex;flex-direction:column\">\n            <div style=\"display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid #f0f4f3\">\n              <span style=\"font-weight:600;font-size:15px\">${esc(title || \"書類\")}</span>\n              <button class=\"ov-close\" style=\"background:none;border:none;font-size:22px;cursor:pointer;color:#999\">×</button>\n            </div>\n            <div class=\"ov-body\" style=\"overflow-y:auto;padding:16px;font-size:13px;line-height:1.8;color:#333;white-space:pre-wrap\">読み込み中...</div>\n          </div>`;\n        document.body.appendChild(overlay);\n        const close = () => overlay.remove();\n        overlay.querySelector(\".ov-close\")?.addEventListener(\"click\", close);\n        overlay.addEventListener(\"click\", (e) => { if (e.target === overlay) close(); });\n        try {\n          const res = await fetch(`${documentBaseUrl}/${docId}`, { headers: { Authorization: `Bearer ${idToken}` } });\n          if (!res.ok) throw new Error(\"本文の取得に失敗しました\");\n          const data = await res.json();\n          overlay.querySelector(\".ov-body\").textContent = data.version?.content || \"(本文がありません)\";\n        } catch (e) {\n          overlay.querySelector(\".ov-body\").textContent = e.message || \"本文の取得に失敗しました\";\n        }\n      }\n\n      // ---- 全項目編集フォーム描画 ----\n      function renderEditForm(profile) {\n        const p = profile || {};\n        const prefectures = [\"北海道\",\"青森県\",\"岩手県\",\"宮城県\",\"秋田県\",\"山形県\",\"福島県\",\"茨城県\",\"栃木県\",\"群馬県\",\"埼玉県\",\"千葉県\",\"東京都\",\"神奈川県\",\"新潟県\",\"富山県\",\"石川県\",\"福井県\",\"山梨県\",\"長野県\",\"岐阜県\",\"静岡県\",\"愛知県\",\"三重県\",\"滋賀県\",\"京都府\",\"大阪府\",\"兵庫県\",\"奈良県\",\"和歌山県\",\"鳥取県\",\"島根県\",\"岡山県\",\"広島県\",\"山口県\",\"徳島県\",\"香川県\",\"愛媛県\",\"高知県\",\"福岡県\",\"佐賀県\",\"長崎県\",\"熊本県\",\"大分県\",\"宮崎県\",\"鹿児島県\",\"沖縄県\"];\n\n        show(`\n          <div class=\"card\" style=\"display:flex;align-items:center;gap:12px;padding:14px 20px;\">\n            <button id=\"btn-back\" style=\"background:none;border:none;font-size:20px;cursor:pointer;padding:0;\">←</button>\n            <span style=\"font-weight:600;font-size:16px;\">プロフィール編集</span>\n          </div>\n          <div class=\"card\">\n            <div style=\"background:#f0f7f4;border-radius:10px;padding:10px 12px;margin-bottom:14px;font-size:12px;color:#4a5f5b;line-height:1.6;\">\n              💡 プロフィールを埋めるほど、条件に合う<strong style=\"color:#2e7d5b\">答えられるアンケートが増えます</strong>。\n              未入力の項目が条件になっているアンケートは届かないことがあるため、任意項目もぜひご登録ください。\n            </div>\n            <form id=\"edit-form\" class=\"form-stack\">\n              <div class=\"form-group\">\n                <label>呼び名</label>\n                <input class=\"form-control\" type=\"text\" name=\"nickname\" value=\"${esc(p.nickname)}\" placeholder=\"例：たろう\" />\n              </div>\n              <div class=\"form-group\">\n                <label>生年月日</label>\n                <input class=\"form-control\" type=\"date\" name=\"birth_date\" value=\"${esc(p.birth_date) || '2000-01-01'}\" max=\"${new Date().toISOString().slice(0,10)}\" />\n              </div>\n              <div class=\"form-group\">\n                <label>都道府県</label>\n                <select class=\"form-control\" name=\"prefecture\">\n                  <option value=\"\">選択してください</option>\n                  ${prefectures.map(pref => `<option value=\"${esc(pref)}\" ${sel(p.prefecture, pref)}>${esc(pref)}</option>`).join(\"\")}\n                </select>\n              </div>\n              <div class=\"form-group\">\n                <label>住所詳細</label>\n                <div class=\"radio-group\" style=\"margin-bottom:8px;\">\n                  <label><input type=\"radio\" name=\"address_declined\" value=\"false\" ${p.address_declined ? \"\" : \"checked\"} />詳細も登録する</label>\n                  <label><input type=\"radio\" name=\"address_declined\" value=\"true\" ${p.address_declined ? \"checked\" : \"\"} />都道府県のみ</label>\n                </div>\n                <div id=\"address-detail-wrap\">\n                  <input class=\"form-control\" type=\"text\" name=\"address_detail\" value=\"${esc(p.address_detail)}\" placeholder=\"例：渋谷区...\" />\n                </div>\n              </div>\n              <div class=\"form-group\">\n                <label>職業</label>\n                <select class=\"form-control\" name=\"occupation\">\n                  <option value=\"\">選択してください</option>\n                  ${[\"会社員（正社員）\",\"会社員（契約・派遣）\",\"公務員\",\"自営業・フリーランス\",\"パート・アルバイト\",\"学生\",\"専業主婦・主夫\",\"無職\",\"その他\"].map(o => `<option value=\"${esc(o)}\" ${sel(p.occupation, o)}>${esc(o)}</option>`).join(\"\")}\n                </select>\n              </div>\n              <div class=\"form-group\">\n                <label>業種</label>\n                <select class=\"form-control\" name=\"industry\">\n                  <option value=\"\">選択してください</option>\n                  ${[\"IT・通信\",\"製造\",\"金融・保険\",\"医療・福祉\",\"教育\",\"小売・流通\",\"外食・フード\",\"建設・不動産\",\"メディア・広告\",\"公共・行政\",\"その他\"].map(i => `<option value=\"${esc(i)}\" ${sel(p.industry, i)}>${esc(i)}</option>`).join(\"\")}\n                </select>\n              </div>\n              <div class=\"form-group\">\n                <label>婚姻状況</label>\n                <div class=\"radio-group\">\n                  ${[[\"single\",\"未婚\"],[\"married\",\"既婚\"],[\"divorced\",\"離婚\"],[\"widowed\",\"死別\"]].map(([v,l]) =>\n                    `<label><input type=\"radio\" name=\"marital_status\" value=\"${v}\" ${chk(p.marital_status, v)} />${l}</label>`\n                  ).join(\"\")}\n                </div>\n              </div>\n              <div class=\"form-group\">\n                <label>子どもの有無</label>\n                <div class=\"radio-group\">\n                  <label><input type=\"radio\" name=\"has_children\" value=\"true\"  ${p.has_children === true  ? \"checked\" : \"\"} />いる</label>\n                  <label><input type=\"radio\" name=\"has_children\" value=\"false\" ${p.has_children === false ? \"checked\" : \"\"} />いない</label>\n                </div>\n              </div>\n              <div class=\"form-group\">\n                <label>子どもの年齢（カンマ区切り）</label>\n                <input class=\"form-control\" type=\"text\" name=\"children_ages_text\" value=\"${esc((p.children_ages||[]).join(\",\"))}\" placeholder=\"例：3,7,12\" />\n              </div>\n              <div class=\"form-group\">\n                <label>同居家族構成（複数選択可）</label>\n                <div class=\"checkbox-group\">\n                  ${[[\"self\",\"本人のみ\"],[\"spouse\",\"配偶者\"],[\"child\",\"子ども\"],[\"parent\",\"親\"],[\"sibling\",\"兄弟姉妹\"],[\"other\",\"その他\"]].map(([v,l]) =>\n                    `<label><input type=\"checkbox\" name=\"household_composition\" value=\"${v}\" ${inArr(p.household_composition, v)} />${l}</label>`\n                  ).join(\"\")}\n                </div>\n              </div>\n              <div class=\"form-group\">\n                <label>世帯年収</label>\n                <select class=\"form-control\" name=\"household_income\">\n                  <option value=\"\">選択してください</option>\n                  ${incomeOptions.map(([v,l]) => `<option value=\"${v}\" ${sel(p.household_income, v)}>${l}</option>`).join(\"\")}\n                </select>\n              </div>\n              <p id=\"edit-status\" class=\"status-msg\"></p>\n              <button type=\"submit\" class=\"btn btn-primary\">保存する</button>\n            </form>\n          </div>\n        `);\n\n        document.getElementById(\"btn-back\")?.addEventListener(\"click\", () => load());\n\n        // 住所詳細表示切替\n        const declineRadios = document.querySelectorAll('input[name=\"address_declined\"]');\n        function toggleAddr() {\n          const declined = document.querySelector('input[name=\"address_declined\"]:checked')?.value === \"true\";\n          const wrap = document.getElementById(\"address-detail-wrap\");\n          if (wrap) wrap.style.display = declined ? \"none\" : \"\";\n        }\n        declineRadios.forEach(r => r.addEventListener(\"change\", toggleAddr));\n        toggleAddr();\n\n        document.getElementById(\"edit-form\")?.addEventListener(\"submit\", async (e) => {\n          e.preventDefault();\n          const form = e.target;\n          const fd = new FormData(form);\n          const statusEl = document.getElementById(\"edit-status\");\n          statusEl.textContent = \"保存中...\";\n          statusEl.className = \"status-msg\";\n\n          const childAges = (fd.get(\"children_ages_text\")||\"\").toString().split(\",\").map(s => parseInt(s.trim(),10)).filter(n => !isNaN(n));\n          const payload = {\n            nickname:             fd.get(\"nickname\") || null,\n            birth_date:           fd.get(\"birth_date\") || null,\n            prefecture:           fd.get(\"prefecture\") || null,\n            address_declined:     fd.get(\"address_declined\") === \"true\",\n            address_detail:       fd.get(\"address_declined\") === \"true\" ? null : (fd.get(\"address_detail\") || null),\n            occupation:           fd.get(\"occupation\") || null,\n            industry:             fd.get(\"industry\") || null,\n            marital_status:       fd.get(\"marital_status\") || null,\n            has_children:         fd.get(\"has_children\") === \"true\" ? true : fd.get(\"has_children\") === \"false\" ? false : null,\n            children_ages:        childAges,\n            household_composition: fd.getAll(\"household_composition\").map(String).filter(Boolean),\n            household_income:     fd.get(\"household_income\") || null,\n          };\n\n          try {\n            const res = await fetch(updateUrl, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\", Authorization: `Bearer ${idToken}` },\n              body: JSON.stringify(payload)\n            });\n            if (!res.ok) throw new Error(\"保存に失敗しました。\");\n            statusEl.textContent = \"保存しました。\";\n            statusEl.className = \"status-msg success\";\n          } catch (err) {\n            statusEl.textContent = err.message || \"保存に失敗しました。\";\n            statusEl.className = \"status-msg error\";\n          }\n        });\n      }\n\n      // ---- 今月の応募状況 ----\n      async function loadMonthlyStats() {\n        if (!historyUrl) return;\n        try {\n          const res = await fetch(historyUrl, { headers: { Authorization: `Bearer ${idToken}` } });\n          if (!res.ok) return;\n          const data = await res.json();\n          const history = data.history || [];\n          const now = new Date();\n          const thisMonth = history.filter(h => {\n            const d = new Date(h.assigned_at || '');\n            return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth();\n          });\n          const completedThisMonth = thisMonth.filter(h => h.status === 'completed');\n          const earnedThisMonth = completedThisMonth.reduce((sum, h) => sum + (h.reward_points || 0), 0);\n\n          const card = document.getElementById('monthly-stats-card');\n          const grid = document.getElementById('monthly-grid');\n          if (!card || !grid) return;\n\n          grid.innerHTML = `\n            <div class=\"monthly-item\">\n              <div class=\"monthly-value\">${thisMonth.length}<span class=\"monthly-unit\">件</span></div>\n              <div class=\"monthly-label\">今月の応募数</div>\n            </div>\n            <div class=\"monthly-item\">\n              <div class=\"monthly-value\">${earnedThisMonth}<span class=\"monthly-unit\">pt</span></div>\n              <div class=\"monthly-label\">今月の獲得ポイント</div>\n            </div>`;\n          card.style.display = '';\n        } catch (_) {}\n      }\n\n      // ---- 同意ゲート ----\n      // バージョン管理されたグローバル必須書類（利用規約・PP）の最新版に未同意なら\n      // 同意画面 /liff/consent へ誘導する。プロフィール登録より前に同意を取得する。\n      // 戻り先として現在のURLを渡し、同意後はこのページに復帰する。\n      async function ensureGlobalConsent() {\n        try {\n          // 同意画面 consent.ejs と同一エンドポイントで判定する（基準を揃えてループを防ぐ）。\n          // count>0 = 未同意 or 改定による要再同意。\n          const res = await fetch('/liff/consent-check', { headers: { Authorization: `Bearer ${idToken}` } });\n          if (!res.ok) return false; // 同意基盤の障害で登録自体を止めない（フェイルオープン）\n          const data = await res.json();\n          if (!data.count) return false;\n          const redirect = encodeURIComponent(location.pathname + location.search);\n          location.href = `/liff/consent?mode=initial&redirect=${redirect}`;\n          return true;\n        } catch {\n          return false;\n        }\n      }\n\n      // ---- メインロード ----\n      async function load() {\n        if (!liffId) {\n          showError(\"LIFF IDが設定されていません。管理者にお問い合わせください。\");\n          return;\n        }\n        try {\n          const token = await LiffAuth.initLiffOrWebAuth(liffId);\n          if (!token) return; // LINE Login リダイレクト中\n          idToken = token;\n\n          // プロフィール表示・登録の前に規約同意を確認（未同意なら同意画面へ離脱）\n          if (await ensureGlobalConsent()) return;\n\n          // 「回答する」タブのバッジ（いま回答できる件数）。この画面の表示はブロックしない。\n          if (window.LiffNavBadge) LiffNavBadge.refresh(idToken);\n\n          // 今日の1問は同意を通った後にだけ出す（マイページの表示はブロックしない）。\n          // 回答でランク/段位が上がったら昇格演出を出す（回答前ランク prev と付与後 next を比較）。\n          DailyToday.mount({\n            idToken,\n            onAnswered: (result) => {\n              try {\n                if (window.RankCelebration && result.pointStatus) {\n                  const prev = lastPointStatus;\n                  RankCelebration.maybePlay(prev, result.pointStatus);\n                  lastPointStatus = result.pointStatus;\n                }\n              } catch (e) { console.error(\"rank celebration failed\", e); }\n            },\n          });\n\n          const res = await fetch(profileUrl, { headers: { Authorization: `Bearer ${idToken}` } });\n          if (!res.ok) {\n            let detail = \"\";\n            try { detail = (await res.json()).detail || \"\"; } catch (_e) {}\n            throw new Error(\"情報の取得に失敗しました。\" + (detail ? \"（\" + detail + \"）\" : \"\") + `[${res.status}]`);\n          }\n          const data = await res.json();\n\n          const forceSetup = mode === \"initial_setup\";\n          const profileIncomplete = !data.profile?.profile_completed;\n\n          if (forceSetup || profileIncomplete) {\n            renderSetupForm(data.profile);\n          } else if (mode === \"edit\") {\n            renderEditForm(data.profile);\n          } else {\n            renderDashboard(data);\n          }\n        } catch (err) {\n          showError(err.message || \"読み込みに失敗しました。\");\n        }\n      }\n\n      void load();\n    })();\n    </script>\n  </body>\n</html>\n")
