    ; __append(escapeFn( JSON.stringify(initialData) ))
    ; __append("'></div>\n\n    <script>\n    (() => {\n      'use strict';\n      const d = JSON.parse(document.getElementById('initial-data').dataset.json || '{}');\n\n      let idToken = null;\n      let project = null;\n      let isSaved = false;\n      let myApplication = null;\n      let myAssignment = null;\n\n      function esc(v) {\n        return String(v ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;');\n      }\n      function daysLeft(iso) {\n        if (!iso) return null;\n        const dd = Math.ceil((new Date(iso).getTime() - Date.now()) / 86400000);\n        return dd < 0 ? null : dd;\n      }\n      function fmtDeadline(iso) {\n        if (!iso) return null;\n        const dt = new Date(iso);\n        const w = ['日','月','火','水','木','金','土'][dt.getDay()];\n        return `${dt.getMonth()+1}月${dt.getDate()}日(${w}) ${String(dt.getHours()).padStart(2,'0')}:${String(dt.getMinutes()).padStart(2,'0')} 締切`;\n      }\n\n      function render() {\n        const isAuto = project.apply_mode === 'auto';\n        const left = daysLeft(project.recruit_deadline);\n        const ngLines = String(project.ng_conditions || '').split('\\n').map(s => s.trim()).filter(Boolean);\n        const el = document.getElementById('content');\n\n        el.innerHTML = `\n          <div class=\"hb-hero\">\n            <div class=\"hb-meta\">\n              <span class=\"hb-badge\">${isAuto ? 'AIインタビュー' : esc(project.interview_format || 'オンラインインタビュー')}</span>\n              <span class=\"hb-badge\">${isAuto ? '⚡ 即回答OK' : '選考あり'}</span>\n            </div>\n            <h3>${esc(project.title)}</h3>\n            <div class=\"t\">${isAuto ? '⚡ 応募後、すぐに回答できます' : '📮 応募 → 選考 → 当選された方のみ実施'}</div>\n            <p>${isAuto\n              ? '選考・日程調整はありません。応募するとそのまま回答が始まり、完了と同時に謝礼が付与されます。'\n              : '応募後に選考を行い、結果はLINEでお知らせします。当選された方に回答のご案内をお送りします。'}</p>\n          </div>\n          <div class=\"hb-stats\">\n            <div class=\"hb-stat\"><div class=\"k\">謝礼</div><div class=\"v\">${(project.reward_points ?? 0).toLocaleString()}<small>pt</small></div></div>\n            <div class=\"hb-stat\"><div class=\"k\">所要時間</div><div class=\"v\">${project.estimated_minutes ? '約' + esc(String(project.estimated_minutes)) + '<small>分</small>' : '-'}</div></div>\n            <div class=\"hb-stat\"><div class=\"k\">締切</div><div class=\"v\">${left !== null ? 'あと' + left + '<small>日</small>' : 'なし'}</div></div>\n          </div>\n\n          ${isAuto ? `\n          <div class=\"hb-panel\">\n            <div class=\"hb-note\" style=\"margin-bottom:8px\">💬 こんなイメージで進みます</div>\n            <div class=\"hb-bub ai\">こんにちは！このテーマについて、いま一番気になっていることを教えてください 😊</div>\n            <div class=\"hb-bub me\">〇〇が気になっています</div>\n            <div class=\"hb-bub ai\">それはどんな場面で感じることが多いですか？</div>\n          </div>` : `\n          <div class=\"hb-panel\">\n            <div class=\"hb-sec-title\">🚩 実施までの流れ</div>\n            <ul class=\"hb-flow\">\n              <li><b>1. 応募する</b><small>ボタンひとつで完了します</small></li>\n              <li><b>2. 選考</b><small>結果はLINEでお知らせします</small></li>\n              <li><b>3. 当選 → 回答のご案内</b><small>届いたURLから回答できます</small></li>\n              <li><b>4. 謝礼 ${(project.reward_points ?? 0).toLocaleString()}pt 付与</b><small>回答完了後に付与されます</small></li>\n            </ul>\n          </div>`}\n\n          ${(project.objective || ngLines.length > 0) ? `\n          <div class=\"hb-panel\">\n            ${project.objective ? `\n              <div class=\"hb-sec-title\">👤 募集内容</div>\n              <p style=\"font-size:14px;line-height:1.8;white-space:pre-wrap\">${esc(project.objective)}</p>` : ''}\n            ${ngLines.length > 0 ? `\n              <div class=\"hb-ngbox\">\n                <div class=\"t\">⚠ NG条件</div>\n                <ul>${ngLines.map(l => '<li>' + esc(l) + '</li>').join('')}</ul>\n              </div>` : ''}\n          </div>` : ''}\n\n          ${project.recruit_deadline ? `\n          <div class=\"hb-panel\">\n            <div class=\"hb-sec-title\">📅 募集期限</div>\n            <p style=\"font-size:15px\">${esc(fmtDeadline(project.recruit_deadline))}</p>\n          </div>` : ''}\n          <div style=\"height:16px\"></div>`;\n\n        el.style.display = '';\n        document.getElementById('loading-overlay').style.display = 'none';\n        renderCta();\n      }\n\n      function renderCta() {\n        const bar = document.getElementById('cta-bar');\n        const applyBtn = document.getElementById('apply-btn');\n        const saveBtn = document.getElementById('save-btn');\n        bar.style.display = '';\n        saveBtn.textContent = isSaved ? '★' : '☆';\n        saveBtn.className = `hb-save${isSaved ? ' saved' : ''}`;\n        applyBtn.classList.add('primary');\n        applyBtn.classList.remove('sub');\n\n        const isAuto = project.apply_mode === 'auto';\n        const appStatus = myApplication ? myApplication.status : null;\n\n        if (myAssignment && myAssignment.status === 'completed') {\n          applyBtn.textContent = '回答済みです';\n          applyBtn.disabled = true;\n        } else if (appStatus === 'accepted' && myApplication.assignment_id) {\n          applyBtn.textContent = '回答をはじめる ⚡';\n          applyBtn.disabled = false;\n          applyBtn.dataset.action = 'answer';\n        } else if (appStatus === 'applied') {\n          applyBtn.textContent = '選考中です（タップで応募を取り消し）';\n          applyBtn.disabled = false;\n          applyBtn.dataset.action = 'withdraw';\n          applyBtn.classList.remove('primary');\n          applyBtn.classList.add('sub');\n        } else if (project.recruit_closed) {\n          applyBtn.textContent = '募集は終了しました';\n          applyBtn.disabled = true;\n        } else {\n          applyBtn.textContent = isAuto ? '応募してすぐ回答する ⚡' : '応募する';\n          applyBtn.disabled = false;\n          applyBtn.dataset.action = 'apply';\n        }\n      }\n\n      function showManualDone() {\n        document.getElementById('content').style.display = 'none';\n        document.getElementById('cta-bar').style.display = 'none';\n        const el = document.getElementById('done');\n        el.innerHTML = `\n          <div class=\"hb-done\">\n            <div class=\"emoji\">📮</div>\n            <h2>応募を受け付けました</h2>\n            <p>選考のうえ、結果はLINEでお知らせします。<br>当選された場合は回答のご案内が届きます。</p>\n            <div class=\"hb-hint hb-mt16\">💡 当選率を上げるには、プロフィールを充実させて、毎月10件以上の応募がおすすめです。</div>\n            <a class=\"hb-btn primary hb-mt16\" href=\"${esc(d.projectsUrl)}\">ほかの案件も探す</a>\n            <a class=\"hb-btn ghost hb-mt12\" href=\"${esc(d.interactionsUrl)}\">応募状況を確認する</a>\n          </div>`;\n        el.style.display = '';\n        window.scrollTo(0, 0);\n      }\n\n      async function ensureConsents() {\n        // 未同意のグローバル必須書類があれば同意ページへ（同意後この画面に戻る）\n        try {\n          const res = await fetch(d.consentCheckUrl, { headers: { Authorization: `Bearer ${idToken}` } });\n          const json = await res.json();\n          if (json.ok && json.count > 0) {\n            const redirect = encodeURIComponent(location.pathname + location.search);\n            window.location.href = `${d.consentPageUrl}?mode=initial&redirect=${redirect}`;\n            return false;\n          }\n        } catch (err) { console.warn('consent-check failed', err); }\n        return true;\n      }\n\n      async function doApply() {\n        const applyBtn = document.getElementById('apply-btn');\n        applyBtn.disabled = true;\n        applyBtn.textContent = '応募しています…';\n\n        if (!(await ensureConsents())) return;\n\n        try {\n          const res = await fetch(d.applyUrl, {\n            method: 'POST',\n            headers: { Authorization: `Bearer ${idToken}` }\n          });\n          const json = await res.json();\n          if (!json.ok) {\n            alert(json.error || '応募できませんでした。');\n            renderCta();\n            return;\n          }\n          if (json.mode === 'auto' && json.survey_url) {\n            // 応募→即回答（選考なし・ワンクッション置かず直行）\n            window.location.href = json.survey_url;\n            return;\n          }\n          myApplication = { status: 'applied', assignment_id: null };\n          showManualDone();\n        } catch (err) {\n          alert('通信に失敗しました。時間をおいて再度お試しください。');\n          renderCta();\n        }\n      }\n\n      async function doWithdraw() {\n        if (!confirm('応募を取り消しますか？')) { renderCta(); return; }\n        try {\n          const res = await fetch(d.withdrawUrl, {\n            method: 'POST',\n            headers: { Authorization: `Bearer ${idToken}` }\n          });\n          const json = await res.json();\n          if (!json.ok) { alert(json.error || '取り消せませんでした。'); return; }\n          myApplication = null;\n          renderCta();\n        } catch (err) { alert('通信に失敗しました。'); }\n      }\n\n      async function load() {\n        try {\n          const token = await LiffAuth.initLiffOrWebAuth(d.liffId);\n          if (!token) return;\n          idToken = token;\n\n          const res = await fetch(d.dataUrl, { headers: { Authorization: `Bearer ${idToken}` } });\n          if (res.status === 404) throw new Error('この案件は現在公開されていません。');\n          const data = await res.json();\n          project = data.project;\n          isSaved = data.is_saved;\n          myApplication = data.my_application;\n          myAssignment = data.my_assignment;\n          render();\n        } catch (err) {\n          document.getElementById('loading-overlay').style.display = 'none';\n          const el = document.getElementById('content');\n          el.style.display = '';\n          el.innerHTML = `<div class=\"hb-empty\"><div class=\"icon\">⚠️</div><p>${esc(err.message || '読み込みに失敗しました')}</p><a class=\"hb-btn ghost hb-mt16\" href=\"${esc(d.projectsUrl)}\" style=\"max-width:280px;margin-left:auto;margin-right:auto\">案件一覧へ戻る</a></div>`;\n        }\n      }\n\n      document.getElementById('back-btn').addEventListener('click', () => {\n        if (history.length > 1) history.back(); else window.location.href = d.projectsUrl;\n      });\n      document.getElementById('save-btn').addEventListener('click', async () => {\n        try {\n          const res = await fetch(d.favoriteUrl, { method: 'POST', headers: { Authorization: `Bearer ${idToken}` } });\n          const json = await res.json();\n          isSaved = json.saved;\n          renderCta();\n        } catch (err) { console.error(err); }\n      });\n      document.getElementById('apply-btn').addEventListener('click', () => {\n        const action = document.getElementById('apply-btn').dataset.action;\n        if (action === 'apply') void doApply();\n        else if (action === 'withdraw') void doWithdraw();\n        else if (action === 'answer' && myApplication && myApplication.assignment_id) {\n          window.location.href = `${d.surveyBaseUrl}/${myApplication.assignment_id}`;\n        }\n      });\n\n      void load();\n    })();\n    </script>\n  </body>\n</html>\n")
