    ; __append("'></div>\n\n    <script>\n    (() => {\n      'use strict';\n      const d = JSON.parse(document.getElementById('initial-data').dataset.json || '{}');\n      const { liffId, projectsDataUrl, projectDetailBaseUrl } = d;\n\n      let idToken = null;\n      let allProjects = [];\n      let filter = 'all';\n      // ミッションの「部屋」からの流入（/liff/projects?category=…）。\n      // カテゴリはミッション側と同じ値（projects.category）なので cat: フィルタに直結できる。\n      // 該当チップがあれば点灯し、無いカテゴリでもフィルタ自体は効かせる。\n      const initialCategory = new URLSearchParams(location.search).get('category');\n      if (initialCategory) {\n        filter = `cat:${initialCategory}`;\n        document.querySelectorAll('.hb-chip').forEach(c => c.classList.remove('on'));\n        const chip = document.querySelector(`.hb-chip[data-filter=\"cat:${CSS.escape(initialCategory)}\"]`);\n        if (chip) chip.classList.add('on');\n      }\n      let searchText = '';\n      // 直近描画したランク状態。回答確定後に旧→新を比べて昇格演出を出すために保持する。\n      let lastPointStatus = null;\n      const SORTS = [\n        { key: 'new',      label: '⇅ 新着順' },\n        { key: 'reward',   label: '⇅ 報酬が高い順' },\n        { key: 'deadline', label: '⇅ 締切が近い順' },\n      ];\n      let sortIdx = 0;\n\n      function esc(v) {\n        return String(v ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;');\n      }\n      function daysAgo(iso) {\n        if (!iso) return null;\n        return Math.floor((Date.now() - new Date(iso).getTime()) / 86400000);\n      }\n      function daysLeft(iso) {\n        if (!iso) return null;\n        const dd = Math.ceil((new Date(iso).getTime() - Date.now()) / 86400000);\n        return dd < 0 ? null : dd;\n      }\n      function fmtBadges(p) {\n        const isNew = (daysAgo(p.created_at) ?? 99) <= 3;\n        const isAuto = p.apply_mode === 'auto';\n        const applied = !!p.application_status && p.application_status !== 'withdrawn';\n        const badges = [];\n        if (applied) badges.push('<span class=\"hb-badge done\">応募済み</span>');\n        if (isNew) badges.push('<span class=\"hb-badge new\">新着</span>');\n        badges.push(isAuto\n          ? '<span class=\"hb-badge ai\">AIインタビュー</span>'\n          : '<span class=\"hb-badge fmt\">' + esc(p.interview_format || 'インタビュー（選考あり）') + '</span>');\n        (p.tags || []).slice(0, 2).forEach(t => badges.push('<span class=\"hb-badge fmt\">#' + esc(t) + '</span>'));\n        return badges.join('');\n      }\n\n      function renderPick(p) {\n        const area = document.getElementById('pick-area');\n        if (!p) { area.innerHTML = ''; return; }\n        area.innerHTML = `\n          <a class=\"hb-pick\" href=\"${esc(projectDetailBaseUrl)}/${esc(p.id)}\">\n            <span class=\"lbl\">✨ 注目の案件</span>\n            <h3>${esc(p.title)}</h3>\n            <div class=\"foot\">\n              <span class=\"price\">${(p.reward_points ?? 0).toLocaleString()}<small>pt${p.estimated_minutes ? '｜' + esc(String(p.estimated_minutes)) + '分' : ''}</small></span>\n              <span class=\"go\">見る ›</span>\n            </div>\n          </a>`;\n      }\n\n      // すきま時間枠の抽出規則。src/lib/quickPickSelection.ts と同じ規則をブラウザ側でも持つ\n      // （テストは純関数側にある。ここを変えるときは向こうも直す）。\n      // ⚠ estimated_minutes が未設定の案件は絶対に入れない。「3分で終わるはずが終わらない」が\n      //    最も信頼を損なうため、「短いと分かっているもの」だけを枠に入れる。\n      const QUICK_MAX_MIN = 5;\n      const QUICK_LIMIT = 8;\n      function isQuickPick(p) {\n        const m = p.estimated_minutes;\n        return typeof m === 'number' && Number.isFinite(m) && m > 0 && m <= QUICK_MAX_MIN;\n      }\n      function selectQuickPicks(list) {\n        return list\n          .filter(isQuickPick)\n          .sort((a, b) => {\n            const d = (a.estimated_minutes ?? 0) - (b.estimated_minutes ?? 0);\n            return d !== 0 ? d : (b.reward_points ?? 0) - (a.reward_points ?? 0);\n          })\n          .slice(0, QUICK_LIMIT);\n      }\n\n      /**\n       * 「すきま時間に」帯を描く。該当0件なら帯ごと消す\n       * （見出しだけ残すと空虚に見えるため、セクションごと空にする）。\n       */\n      function renderQuickPicks(list) {\n        const area = document.getElementById('quick-area');\n        if (!area) return;\n        const picks = selectQuickPicks(list);\n        if (picks.length === 0) { area.innerHTML = ''; return; }\n\n        area.innerHTML = `\n          <section class=\"hb-quick\">\n            <div class=\"hb-h\">\n              <svg class=\"hb-h-ico\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></svg>\n              <span>すきま時間に</span>\n              <span class=\"why\">${QUICK_MAX_MIN}分以内 · ${picks.length}件</span>\n            </div>\n            <div class=\"rail\">\n              ${picks.map(p => `\n                <a class=\"qcard\" href=\"${esc(projectDetailBaseUrl)}/${esc(p.id)}\" data-quick-id=\"${esc(p.id)}\">\n                  <div class=\"qtop\">\n                    <span class=\"qpt\">${(p.reward_points ?? 0).toLocaleString()}</span>\n                    <span class=\"qunit\">pt</span>\n                    <span class=\"qmin\">${esc(String(p.estimated_minutes))}分</span>\n                  </div>\n                  <div class=\"qttl\">${esc(p.title)}</div>\n                </a>`).join('')}\n            </div>\n          </section>`;\n\n        // すきま帯からの流入を一覧タップと区別できるよう接頭辞を付けて計測する。\n        area.querySelectorAll('[data-quick-id]').forEach(el => {\n          el.addEventListener('click', () => {\n            if (window.HbTrack) {\n              window.HbTrack.push('card_tap', 'quick:' + el.dataset.quickId, null);\n              window.HbTrack.flush();\n            }\n          });\n        });\n      }\n\n      function renderProjects(list) {\n        const listEl = document.getElementById('project-list');\n        document.getElementById('loading-overlay').style.display = 'none';\n        listEl.style.display = '';\n        document.getElementById('list-head').style.display = '';\n\n        if (list.length === 0) {\n          listEl.innerHTML = '<div class=\"hb-empty\"><div class=\"icon\">🔍</div><p>該当する案件がありません</p></div>';\n          return;\n        }\n\n        listEl.innerHTML = list.map(p => {\n          const left = daysLeft(p.recruit_deadline);\n          const isAuto = p.apply_mode === 'auto';\n          return `\n            <article class=\"hb-card\" data-id=\"${esc(p.id)}\">\n              <div class=\"pt ${isAuto ? 'hot' : ''}\">\n                <small>${isAuto ? '⚡即回答' : '謝礼'}</small>\n                <b>${(p.reward_points ?? 0).toLocaleString()}<small>pt</small></b>\n                ${p.estimated_minutes ? `<div class=\"min\">⏱ ${esc(String(p.estimated_minutes))}分</div>` : ''}\n                <div class=\"qchip\">🌱 満額</div>\n              </div>\n              <div class=\"body\">\n                <h3>${esc(p.title)}</h3>\n                <div class=\"hb-meta\">${fmtBadges(p)}</div>\n                <div class=\"hb-foot\">\n                  ${left !== null ? `<span class=\"days\">あと<b>${left}</b>日</span>` : ''}\n                  <button class=\"hb-save ${p.is_saved ? 'saved' : ''}\" data-id=\"${esc(p.id)}\">${p.is_saved ? '★ 保存済' : '☆ 保存'}</button>\n                </div>\n              </div>\n            </article>`;\n        }).join('');\n\n        // 案件一覧の見出しに到達したかを1度だけ記録する。\n        // 「進捗ブロックが多すぎて一覧まで届いていないのでは」を実データで検証するための計測\n        // （value_num にその時点のスクロール量が入るので、どれだけ下げて着いたかも残る）。\n        if (window.HbTrack) {\n          window.HbTrack.observeReach(document.getElementById('list-head'), 'list_reach', 'project_list');\n        }\n\n        listEl.querySelectorAll('.hb-card').forEach(card => {\n          card.addEventListener('click', e => {\n            if (e.target.closest('.hb-save')) return;\n            if (window.HbTrack) {\n              window.HbTrack.push('card_tap', card.dataset.id, null);\n              window.HbTrack.flush();\n            }\n            window.location.href = `${projectDetailBaseUrl}/${card.dataset.id}`;\n          });\n        });\n        listEl.querySelectorAll('.hb-save').forEach(btn => {\n          btn.addEventListener('click', async e => {\n            e.stopPropagation();\n            const projectId = btn.dataset.id;\n            try {\n              const res = await fetch(`/liff/projects/${projectId}/favorite`, {\n                method: 'POST',\n                headers: { Authorization: `Bearer ${idToken}` }\n              });\n              const json = await res.json();\n              btn.textContent = json.saved ? '★ 保存済' : '☆ 保存';\n              btn.className = `hb-save${json.saved ? ' saved' : ''}`;\n              const proj = allProjects.find(p => p.id === projectId);\n              if (proj) proj.is_saved = json.saved;\n              // 保存が実際に使われているかの実データ。ボトムナビから保存タブを外してよいかの根拠になる\n              // （value_num: 1=保存した / 0=解除した）。\n              if (window.HbTrack) window.HbTrack.push('save_toggle', projectId, json.saved ? 1 : 0);\n            } catch (err) { console.error('save failed', err); }\n          });\n        });\n      }\n\n      function applyFilters() {\n        let list = allProjects;\n        if (filter.startsWith('cat:')) {\n          const cat = filter.slice(4);\n          list = list.filter(p => p.category === cat);\n        } else if (filter === 'instant') {\n          list = list.filter(p => p.apply_mode === 'auto');\n        }\n        if (searchText) {\n          const q = searchText.toLowerCase();\n          list = list.filter(p =>\n            String(p.title).toLowerCase().includes(q) ||\n            (p.tags || []).some(t => String(t).toLowerCase().includes(q)));\n        }\n        const sort = SORTS[sortIdx].key;\n        if (sort === 'reward') list = [...list].sort((a, b) => (b.reward_points ?? 0) - (a.reward_points ?? 0));\n        if (sort === 'deadline') list = [...list].sort((a, b) => {\n          const at = a.recruit_deadline ? new Date(a.recruit_deadline).getTime() : Infinity;\n          const bt = b.recruit_deadline ? new Date(b.recruit_deadline).getTime() : Infinity;\n          return at - bt;\n        });\n        // すきま時間帯は「いま絞り込んでいる結果」の中から出す。\n        // 検索・カテゴリを当てた状態で無関係な案件が横帯に残ると、絞り込んだ意味が消えるため。\n        renderQuickPicks(list);\n\n        // 先頭1件をヒーローに、残りをリストに（1件しかない場合はヒーローのみ）\n        renderPick(list[0] ?? null);\n        renderProjects(list.slice(1));\n      }\n\n      // ランクを表すメダル。ranks.badge_label は環境で絵文字/英字と不一致なので、\n      // 表示用メダルは rank_code / rank_name から決め打ちする（データに依存させない）。\n      // 順序: … → プラチナ → エメラルド → ダイヤモンド → マスター（migration 081）\n      const RANK_MEDAL = { bronze: '🥉', silver: '🥈', gold: '🥇', platinum: '💠', emerald: '💚', diamond: '💎', master: '👑' };\n      const RANK_MEDAL_JP = { 'ブロンズ': '🥉', 'シルバー': '🥈', 'ゴールド': '🥇', 'プラチナ': '💠', 'エメラルド': '💚', 'ダイヤモンド': '💎', 'マスター': '👑' };\n      function rankMedal(name, code) {\n        return RANK_MEDAL_JP[name] || RANK_MEDAL[String(code || '').toLowerCase()] || '🏅';\n      }\n\n      const TIER_ROMAN = { 1: 'I', 2: 'II', 3: 'III' };\n\n      /**\n       * 現在の段位 → 次の段位 の「旅路」バー。\n       * 左端メダル＝今のランク／右端メダル＝次の目標（同ランク次段位 or 昇格先ランク）。\n       * 段位フィールド（Phase 2）が来ていればそれを、無ければ旧ランクベースにフォールバックする。\n       * gained を渡すと「+15pt」を一瞬出す（デイリー回答直後の加算を見せるため）。\n       */\n      function renderPointCard(status, gained) {\n        const el = document.getElementById('point-card');\n        if (!el || !status) return;\n        lastPointStatus = status;\n\n        const rankName = status.rank_name || 'ブロンズ';\n        const tier = status.tier || null;\n        // SVG アイコン（rank-icons.js）。読み込み前や rank_code 不明時は絵文字にフォールバック。\n        const ICON_SIZE = 42;\n        const medalOf = (code, name, t) =>\n          (window.RankIcons && code) ? RankIcons.badge(code, t || 1, ICON_SIZE) : rankMedal(name, code);\n        const curMedal = medalOf(status.rank_code, rankName, tier || 1);\n        const curLabel = tier ? `${esc(rankName)} ${TIER_ROMAN[tier]}` : esc(rankName);\n        const gainTag = gained > 0 ? `<span class=\"gain\">+${esc(String(gained))}pt</span>` : '';\n\n        let fill, nextMedal, nextName, togo;\n        const hasTier = tier != null && status.tier_progress_pct != null;\n        if (hasTier) {\n          // ── 段位ベース（Phase 2）──\n          if (status.points_to_next_tier == null) {\n            // 最上位ランクの最上位段位（上限なし）\n            fill = 100; nextMedal = '🏆'; nextName = '最上位';\n            togo = `<b>最上位に到達しています 🎉</b>`;\n          } else {\n            const tpct = Math.max(0, Math.min(100, Number(status.tier_progress_pct) || 0));\n            fill = tpct > 0 ? Math.max(tpct, 4) : 0;\n            if (status.next_tier_promotes && status.next_rank_code) {\n              nextMedal = medalOf(status.next_rank_code, status.next_rank_name, 1);\n              nextName = `${esc(status.next_rank_name)} I`;\n            } else {\n              nextMedal = medalOf(status.rank_code, rankName, tier + 1);\n              nextName = `${esc(rankName)} ${TIER_ROMAN[tier + 1] || ''}`;\n            }\n            togo = `次の段位まで <b>あと ${esc(String(status.points_to_next_tier))}pt</b>`;\n          }\n        } else {\n          // ── フォールバック（旧・ランクベース）──\n          const pct = Math.max(0, Math.min(100, Number(status.progress_pct) || 0));\n          fill = pct > 0 ? Math.max(pct, 4) : 0;\n          const hasNext = status.next_rank_name && status.points_to_next != null;\n          nextMedal = hasNext ? medalOf(status.next_rank_code, status.next_rank_name, 1) : '🏆';\n          nextName = hasNext ? esc(status.next_rank_name) : '最上位';\n          togo = hasNext\n            ? `次のランクまで <b>あと ${esc(String(status.points_to_next))}pt</b>`\n            : `<b>最上位ランクに到達しています 🎉</b>`;\n        }\n\n        el.href = d.mypageUrl || '#';\n        // 初期 style=\"display:none\" を外す。CSS 側の flex を効かせるため空文字で戻す\n        // （'block' を入れると1行レイアウトが崩れる）。\n        el.style.display = '';\n        // 1行のステータス帯（案B）。以前は pt カードと「今月の応募数」が別々の大きなブロックで、\n        // 「あなたの進捗」を訴える要素が3つ縦に並び、案件一覧が初期表示に入らなかった。\n        // ここに pt・ランク・今月の応募数を畳んで、一覧を画面内へ持ち上げる。\n        el.innerHTML = `\n          <span class=\"medal\">${curMedal}</span>\n          <div class=\"meat\">\n            <div class=\"line1\">\n              <span class=\"val\">${esc(String(status.available_points ?? 0))}</span><span class=\"unit\">pt</span>${gainTag}\n              <span class=\"togo\">${togo}</span>\n            </div>\n            <div class=\"bar\"><i style=\"width:${fill}%\"></i></div>\n            <div class=\"line2\">\n              <span class=\"cur\">${curLabel}</span>\n              <span class=\"nxt\">次: ${nextMedal} ${nextName}</span>\n              <span class=\"mon\" id=\"monthly-inline\"></span>\n            </div>\n          </div>`;\n        renderMonthlyInline();\n      }\n\n      // 今月の応募数。旧 .hb-progress ブロックの中身を1行帯の中に畳んだもの\n      // （数字は残すが、独立したブロックとしては主張させない）。\n      let monthlyState = { count: 0, reco: 10 };\n      function renderMonthlyInline() {\n        const el = document.getElementById('monthly-inline');\n        if (!el) return;\n        el.innerHTML = `今月 <b>${monthlyState.count}</b>/${monthlyState.reco}件`;\n      }\n\n      async function load() {\n        try {\n          const token = await LiffAuth.initLiffOrWebAuth(liffId);\n          if (!token) return;\n          idToken = token;\n\n          // 今日の1問は案件一覧の表示をブロックしない（失敗してもカードを出さないだけ）。\n          // 回答が確定したら、上のポイントカードを付与後の値に差し替える。\n          // 回答確定時にポイントカードを付与後の値へ差し替え＋昇格演出を通す共通処理。\n          const onPointGained = (result) => {\n            const gained = (result.pointsAwarded ?? 0) + (result.streakBonusAwarded ?? 0);\n            // 昇格判定は「回答前の状態(prev)」と「付与後の状態(result.pointStatus)」で行う。\n            // renderPointCard が lastPointStatus を上書きするので、その前に prev を退避する。\n            const prev = lastPointStatus;\n            renderPointCard(result.pointStatus, gained);\n            try {\n              if (window.RankCelebration) RankCelebration.maybePlay(prev, result.pointStatus);\n            } catch (e) { console.error('rank celebration failed', e); }\n          };\n\n          // 「回答する」タブのバッジ（いま回答できる件数）。一覧表示はブロックしない。\n          if (window.LiffNavBadge) LiffNavBadge.refresh(idToken);\n\n          DailyToday.mount({ idToken, url: d.dailyTodayUrl, onAnswered: onPointGained });\n\n          // ついでスワイプ（脇役）。今日の1問と同じく一覧表示はブロックしない。\n          // プール回答でも累計ptは動くので同じ onAnswered を通す。\n          if (window.PoolSwipe) {\n            PoolSwipe.mount({ idToken, url: d.poolQuestionsTodayUrl, onAnswered: onPointGained });\n          }\n\n          const _fetchStart = performance.now();\n          const res = await fetch(projectsDataUrl, { headers: { Authorization: `Bearer ${idToken}` } });\n          const data = await res.json();\n          const _dataMs = performance.now() - _fetchStart;\n          allProjects = data.projects || [];\n\n          // 今月の応募数はステータス帯の中に畳んで出すので、描画前に値を入れておく\n          // （renderPointCard が帯ごと組み立て直すため、順序が逆だと反映されない）。\n          const monthly = data.monthly_applications;\n          if (monthly) {\n            monthlyState = { count: monthly.count, reco: monthly.recommended };\n          }\n          renderPointCard(data.point_status, 0);\n          const _renderStart = performance.now();\n          applyFilters();\n          try { LiffAuth.reportPerf('/liff/projects', { dataMs: _dataMs, renderMs: performance.now() - _renderStart }); } catch (_e) {}\n        } catch (err) {\n          document.getElementById('loading-overlay').style.display = 'none';\n          const listEl = document.getElementById('project-list');\n          listEl.style.display = '';\n          listEl.innerHTML = `<div class=\"hb-empty\"><div class=\"icon\">⚠️</div><p>${esc(err.message || '読み込みに失敗しました')}</p></div>`;\n        }\n      }\n\n      document.getElementById('chip-bar').addEventListener('click', e => {\n        const chip = e.target.closest('.hb-chip');\n        if (!chip) return;\n        document.querySelectorAll('.hb-chip').forEach(c => c.classList.remove('on'));\n        chip.classList.add('on');\n        filter = chip.dataset.filter;\n        applyFilters();\n      });\n      document.getElementById('search-input').addEventListener('input', e => {\n        searchText = e.target.value.trim();\n        applyFilters();\n      });\n      document.getElementById('sort-fab').addEventListener('click', () => {\n        sortIdx = (sortIdx + 1) % SORTS.length;\n        document.getElementById('sort-fab').textContent = SORTS[sortIdx].label;\n        applyFilters();\n      });\n\n      void load();\n    })();\n    </script>\n  </body>\n</html>\n")
